// Phase 0 discovery probe (throwaway). D1: fastcdc API/determinism/caps.
// D2: blake3 API. D5: serde_ipld_dagcbor determinism + round-trip.

use std::collections::BTreeMap;
use serde::{Deserialize, Serialize};

fn lcg_data(len: usize, seed: u64) -> Vec<u8> {
    // Deterministic pseudo-random bytes (LCG) so runs are reproducible.
    let mut state = seed;
    (0..len)
        .map(|_| {
            state = state.wrapping_mul(6364136223846793005).wrapping_add(1442695040888963407);
            (state >> 33) as u8
        })
        .collect()
}

fn probe_fastcdc() {
    const MIN: u32 = 64 * 1024;
    const AVG: u32 = 256 * 1024;
    const MAX: u32 = 1024 * 1024;
    let data = lcg_data(8 * 1024 * 1024, 42);

    let run = |bytes: &[u8]| -> Vec<(usize, usize)> {
        fastcdc::v2020::FastCDC::new(bytes, MIN, AVG, MAX)
            .map(|c| (c.offset, c.length))
            .collect()
    };

    let a = run(&data);
    let b = run(&data);
    println!("D1 fastcdc v2020: chunks={} deterministic={}", a.len(), a == b);
    let max_len = a.iter().map(|&(_, l)| l).max().unwrap();
    let min_len = a.iter().map(|&(_, l)| l).min().unwrap();
    let total: usize = a.iter().map(|&(_, l)| l).sum();
    println!(
        "D1 caps: max_chunk={} (<=1MiB {}) min_chunk={} coverage={}",
        max_len,
        max_len <= MAX as usize,
        min_len,
        total == data.len()
    );

    // 1-byte insert locality: chunks after the edit window should re-align.
    let mut edited = data.clone();
    edited.insert(4 * 1024 * 1024, 0xAB);
    let c = run(&edited);
    let a_set: std::collections::HashSet<_> =
        a.iter().map(|&(o, l)| blake3::hash(&data[o..o + l])).collect();
    let unchanged = c
        .iter()
        .filter(|&&(o, l)| a_set.contains(&blake3::hash(&edited[o..o + l])))
        .count();
    println!("D1 locality: {}/{} chunks identical after 1-byte insert", unchanged, c.len());
}

fn probe_blake3() {
    let data = b"ciss probe";
    let one = blake3::hash(data);
    let bytes: &[u8; 32] = one.as_bytes();
    let hex = one.to_hex();
    let mut hasher = blake3::Hasher::new();
    hasher.update(b"ciss ");
    hasher.update(b"probe");
    let streamed = hasher.finalize();
    println!(
        "D2 blake3: hex_len={} streaming_matches={} bytes32_ok={}",
        hex.len(),
        streamed == one,
        bytes.len() == 32
    );
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
struct Entry {
    mode: u32,
    mtime: i64,
    size: u64,
    chunks: Vec<[u8; 32]>,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
struct Fs {
    kind: String,
    entries: BTreeMap<String, Entry>,
}

fn probe_dagcbor() {
    let entry = |seed: u64| Entry {
        mode: 0o644,
        mtime: 1_722_000_000,
        size: 3,
        chunks: vec![*blake3::hash(&seed.to_le_bytes()).as_bytes()],
    };
    // Two construction orders; BTreeMap normalizes iteration.
    let mut m1 = BTreeMap::new();
    m1.insert("b".to_string(), entry(1));
    m1.insert("aa".to_string(), entry(2));
    let mut m2 = BTreeMap::new();
    m2.insert("aa".to_string(), entry(2));
    m2.insert("b".to_string(), entry(1));
    let fs1 = Fs { kind: "croft.fs-manifest/v1".into(), entries: m1 };
    let fs2 = Fs { kind: "croft.fs-manifest/v1".into(), entries: m2 };

    let e1 = serde_ipld_dagcbor::to_vec(&fs1).expect("encode");
    let e1b = serde_ipld_dagcbor::to_vec(&fs1).expect("encode");
    let e2 = serde_ipld_dagcbor::to_vec(&fs2).expect("encode");
    let back: Fs = serde_ipld_dagcbor::from_slice(&e1).expect("decode");
    println!(
        "D5 dagcbor: repeat_stable={} insert_order_stable={} roundtrip={} len={}",
        e1 == e1b,
        e1 == e2,
        back == fs1,
        e1.len()
    );
    // Key ordering on the wire: does the encoder use canonical DAG-CBOR
    // (length-first) or the BTreeMap's lexicographic order for "aa" vs "b"?
    let pos_aa = e1.windows(2).position(|w| w == b"aa");
    let pos_b = e1
        .windows(2)
        .position(|w| w[0] == 0x61 && w[1] == b'b'); // 0x61 = 1-byte text string header
    println!("D5 wire order: pos(aa)={:?} pos(0x61 b)={:?}", pos_aa, pos_b);
}

fn main() {
    probe_fastcdc();
    probe_blake3();
    probe_dagcbor();
}

