        assert!(u64::from(c.chunk_ref.len) < ciss::blobstore::MAX_OBJECT_BYTES);
        assert_eq!(c.range.start, expected_start, "chunks must tile contiguously");
        assert_eq!(c.range.len(), c.chunk_ref.len as usize);
