1	//! Workflow tier — `sync backup` (M1 Phase 2). One device pushes a tree to an
2	//! in-process CISS: only missing chunks transfer, the fs-manifest blob is
3	//! stored, and the keep-set Manifest advances under the I5 seq-CAS. This is
4	//! the phase's wiring test: it proves the engine reaches the real server
5	//! boundary, not just that the chunker works.
6	
7	mod common;
8	
9	use std::collections::HashSet;
10	use std::fs;
11	use std::sync::atomic::{AtomicU64, Ordering};
12	
13	use ciss_cli::client::{self, Client};
14	use ciss_cli::sync::HttpCiss;
15	use ciss_sync::{backup, BlobTransport, DagCbor, ManifestCodec, ManifestSlot, SyncError};
16	use common::World;
17	
18	fn build_tree(root: &std::path::Path) {
19	    fs::create_dir_all(root.join("sub")).expect("mkdir");
20	    fs::write(root.join("small.txt"), b"hello sync").expect("write");
21	    let big: Vec<u8> = (0..2 * 1024 * 1024 + 999).map(|i| (i % 249) as u8).collect();
22	    fs::write(root.join("sub/big.bin"), big).expect("write");
23	}
24	
25	fn syncer(world: &World) -> HttpCiss {
26	    let keypair = ciss::crypto::derive_keypair("flow-master", "syncer");
27	    HttpCiss::new(Client::new(world.url("")), keypair)
28	}
29	
30	/// The core backup story: first push uploads everything + the fs-manifest and
31	/// commits keep-set seq 1; an unchanged re-push uploads **zero** chunks
32	/// (have/want skip) and the keep-set still advances strictly (I5).
33	#[tokio::test]
34	async fn backup_uploads_once_then_skips_and_keep_set_advances_under_i5() {
35	    let world = World::spawn().await;
36	    let server = syncer(&world);
37	    let dir = tempfile::tempdir().expect("tempdir");
38	    build_tree(dir.path());
39	
40	    // First backup: everything transfers.
41	    let r1 = backup(dir.path(), &server, None).await.expect("backup 1");
42	    assert_eq!(r1.files, 2);
43	    assert!(r1.chunks_total >= 3, "the 2 MiB file must chunk (got {})", r1.chunks_total);
44	    assert_eq!(r1.chunks_uploaded, r1.chunks_total, "cold server: all chunks upload");
45	    assert_eq!(r1.manifest_seq, 1, "the first keep-set commit is seq 1");
46	
47	    // The fs-manifest blob is stored and decodes back to a manifest whose
48	    // content_id is the stored cid (the address is the server's own sha-256).
49	    let keypair = ciss::crypto::derive_keypair("flow-master", "syncer");
50	    let session = client::session_for(&keypair);
51	    let fetched = server
52	        .client()
53	        .get_s3(Some(&session), &session.did, &r1.fs_manifest_cid)
54	        .await
55	        .expect("fs-manifest stored");
56	    let decoded = DagCbor.decode(&fetched.bytes).expect("decode fs-manifest");
57	    assert_eq!(decoded.content_id().expect("cid"), r1.fs_manifest_cid);
58	    assert_eq!(decoded.entries.len(), 2);
59	
60	    // The keep-set Manifest names every chunk cid + the fs-manifest cid.
61	    let keep = server
62	        .client()
63	        .get_manifest(&session.did)
64	        .await
65	        .expect("get_manifest")
66	        .expect("a keep-set exists after backup");
67	    assert_eq!(keep.seq(), 1);
68	    let leaf_cids: HashSet<&str> = keep.leaves().iter().map(|l| l.cid()).collect();
69	    assert!(leaf_cids.contains(r1.fs_manifest_cid.as_str()));
70	    for entry in decoded.entries.values() {
71	        for c in &entry.chunks {
72	            assert!(leaf_cids.contains(c.sha256_hex().as_str()), "keep-set must hold every chunk");
73	        }
74	    }
75	
76	    // Unchanged re-push: zero chunks move, seq still strictly advances.
77	    let r2 = backup(dir.path(), &server, None).await.expect("backup 2");
78	    assert_eq!(r2.chunks_uploaded, 0, "have/want must skip everything");
79	    assert_eq!(r2.bytes_uploaded, 0);
80	    assert_eq!(r2.manifest_seq, 2, "keep-set commits are strictly newer (I5)");
81	
82	    // I5 guard: a stale/equal-seq commit is refused by the server and surfaced
83	    // as an error, never swallowed.
84	    let stale = ciss::manifest::build_manifest(
85	        &[ciss::manifest::ManifestLeaf::new(&r1.fs_manifest_cid, 1)],
86	        &session.did,
87	        &keypair,
88	        2, // equal to the stored seq — I5 demands strictly newer
89	    );
90	    let err = server
91	        .client()
92	        .put_manifest(&session, &stale)
93	        .await
94	        .expect_err("an equal-seq manifest must be refused");
95	    assert!(err.to_string().contains("seq"), "the error names the seq conflict: {err}");
96	
97	    world.shutdown().await;
98	}
99	
100	/// A transport that fails after `allow` puts — the "network died mid-backup"
101	/// story. The re-run must transfer only what is still missing (chunk-level
102	/// resume replaces byte-range resume).
103	struct FailAfter<'a> {
104	    inner: &'a HttpCiss,
105	    allow: u64,
106	    puts: AtomicU64,
107	}
108	
109	#[async_trait::async_trait]
110	impl BlobTransport for FailAfter<'_> {
111	    async fn have(&self) -> Result<HashSet<String>, SyncError> {
112	        self.inner.have().await
113	    }
114	    async fn put(&self, cid_hex: &str, bytes: &[u8]) -> Result<(), SyncError> {
115	        if self.puts.fetch_add(1, Ordering::SeqCst) >= self.allow {
116	            return Err(SyncError::Transport("injected: connection lost".to_owned()));
117	        }
118	        self.inner.put(cid_hex, bytes).await
119	    }
120	    async fn get(&self, cid_hex: &str) -> Result<Vec<u8>, SyncError> {
121	        self.inner.get(cid_hex).await
122	    }
123	}
124	
125	#[async_trait::async_trait]
126	impl ManifestSlot for FailAfter<'_> {
127	    async fn current_seq(&self) -> Result<Option<u64>, SyncError> {
128	        self.inner.current_seq().await
129	    }
130	    async fn commit_keep_set(
131	        &self,
132	        leaves: &[(String, u64)],
133	        seq: u64,
134	    ) -> Result<(), SyncError> {
135	        self.inner.commit_keep_set(leaves, seq).await
136	    }
137	}
138	
139	#[tokio::test]
140	async fn interrupted_backup_resumes_by_skipping_stored_chunks() {
141	    let world = World::spawn().await;
142	    let server = syncer(&world);
143	    let dir = tempfile::tempdir().expect("tempdir");
144	    build_tree(dir.path());
145	
146	    // Fail after 2 chunk uploads: the backup must error (fail loud, no
147	    // partial keep-set commit pretending success).
148	    let flaky = FailAfter { inner: &server, allow: 2, puts: AtomicU64::new(0) };
149	    let err = backup(dir.path(), &flaky, None).await.expect_err("must fail mid-transfer");
150	    assert!(err.to_string().contains("connection lost"), "surfaced: {err}");
151	    let keypair = ciss::crypto::derive_keypair("flow-master", "syncer");
152	    let session = client::session_for(&keypair);
153	    assert!(
154	        server.client().get_manifest(&session.did).await.expect("get").is_none(),
155	        "an interrupted backup must not commit a keep-set"
156	    );
157	
158	    // The re-run transfers only the chunks the server still lacks.
159	    let resumed = backup(dir.path(), &server, None).await.expect("resume");
160	    assert!(
161	        resumed.chunks_uploaded < resumed.chunks_total,
162	        "resume must skip the {} chunks that already landed",
163	        2
164	    );
165	    assert_eq!(resumed.manifest_seq, 1, "the first successful commit is seq 1");
166	
167	    world.shutdown().await;
168	}

