1	//! The backup flow: scan → have/want diff → upload only what's missing →
2	//! commit the keep-set. Fail loud at every step — an interrupted backup
3	//! never commits a keep-set, and the next run resumes by skipping whatever
4	//! already landed (chunk-level resume; CISS has no byte-range resume).
5	
6	use std::collections::{HashMap, HashSet};
7	use std::fs;
8	use std::path::Path;
9	
10	use crate::chunk::{chunk_file, ChunkRef};
11	use crate::error::SyncError;
12	use crate::index::Index;
13	use crate::manifest::{DagCbor, ManifestCodec};
14	use crate::scan::{scan_tree, scan_tree_indexed};
15	use crate::transport::{missing_blobs, BlobTransport, ManifestSlot};
16	
17	/// What a backup did — the numbers the CLI prints and the flow tests assert.
18	#[derive(Debug, Clone)]
19	pub struct BackupReport {
20	    /// Files in the scanned tree.
21	    pub files: u64,
22	    /// Distinct chunks the tree references.
23	    pub chunks_total: u64,
24	    /// Chunks actually transferred (the have/want complement).
25	    pub chunks_uploaded: u64,
26	    /// Bytes actually transferred (chunks + the fs-manifest blob if it moved).
27	    pub bytes_uploaded: u64,
28	    /// The fs-manifest blob's content id (= its stored cid).
29	    pub fs_manifest_cid: String,
30	    /// The keep-set seq this backup committed.
31	    pub manifest_seq: u64,
32	}
33	
34	/// Back up `dir` to `server`: upload the chunks and fs-manifest the server
35	/// lacks, then commit the keep-set (∪ chunk cids + fs-manifest cid) at
36	/// `last_seq + 1`. Pass an [`Index`] to skip re-chunking probably-unchanged
37	/// files (the index must live *outside* `dir`).
38	///
39	/// # Errors
40	///
41	/// Any scan, transport, cid-mismatch (G3), or keep-set-commit failure — an
42	/// error before the final commit leaves the previous keep-set untouched.
43	pub async fn backup<S>(
44	    dir: &Path,
45	    server: &S,
46	    index: Option<&mut Index>,
47	) -> Result<BackupReport, SyncError>
48	where
49	    S: BlobTransport + ManifestSlot + Sync,
50	{
51	    // 1. Scan.
52	    let manifest = match index {
53	        Some(idx) => scan_tree_indexed(dir, idx)?,
54	        None => scan_tree(dir)?,
55	    };
56	    let manifest_bytes = DagCbor.encode(&manifest)?;
57	    let fs_manifest_cid = manifest.content_id()?;
58	
59	    // 2. The full blob set this tree needs: every distinct chunk + the
60	    // fs-manifest blob itself (first-seen order; dedup within the tree).
61	    let mut needed: Vec<(String, u64)> = Vec::new();
62	    let mut seen: HashSet<String> = HashSet::new();
63	    for entry in manifest.entries.values() {
64	        for c in &entry.chunks {
65	            let cid = c.sha256_hex();
66	            if seen.insert(cid.clone()) {
67	                needed.push((cid, u64::from(c.len)));
68	            }
69	        }
70	    }
71	    let chunks_total = needed.len() as u64;
72	    needed.push((fs_manifest_cid.clone(), manifest_bytes.len() as u64));
73	
74	    // 3. have/want.
75	    let have = server.have().await?;
76	    let want = missing_blobs(needed.clone(), &have);
77	    let want_bytes: u64 = want.iter().map(|(_, b)| b).sum();
78	    let want_cids: HashSet<&str> = want.iter().map(|(c, _)| c.as_str()).collect();
79	    let chunks_to_upload =
80	        want.iter().filter(|(c, _)| c != &fs_manifest_cid).count() as u64;
81	    // The pre-transfer pricing line: the exact number a cost ceiling will
82	    // compare against, logged before any byte moves (the M5 cost-twin embryo).
83	    tracing::info!(
84	        chunks = chunks_to_upload,
85	        bytes = want_bytes,
86	        skipped = chunks_total - chunks_to_upload,
87	        "will upload"
88	    );
89	
90	    // 4. Upload missing chunks, re-reading each file that owns one. The
91	    // re-chunk must reproduce the scanned refs — a file that changed since
92	    // the scan fails the backup rather than uploading a tree the manifest
93	    // doesn't describe.
94	    let mut chunks_uploaded = 0u64;
95	    let mut bytes_uploaded = 0u64;
96	    for (path, entry) in &manifest.entries {
97	        let entry_cids: Vec<String> = entry.chunks.iter().map(ChunkRef::sha256_hex).collect();
98	        if !entry_cids.iter().any(|c| want_cids.contains(c.as_str())) {
99	            tracing::debug!(path = %path, chunks = entry.chunks.len(), "all chunks present");
100	            continue;
101	        }
102	        let file_path = dir.join(path);
103	        let bytes = fs::read(&file_path)
104	            .map_err(|e| SyncError::Io { path: file_path.clone(), source: e })?;
105	        let rechunked = chunk_file(&bytes);
106	        let by_cid: HashMap<String, &std::ops::Range<usize>> =
107	            rechunked.iter().map(|c| (c.chunk_ref.sha256_hex(), &c.range)).collect();
108	        if rechunked.len() != entry.chunks.len()
109	            || !entry_cids.iter().all(|c| by_cid.contains_key(c))
110	        {
111	            return Err(SyncError::ChangedDuringBackup { path: path.clone() });
112	        }
113	        for cid in &entry_cids {
114	            if !want_cids.contains(cid.as_str()) {
115	                tracing::debug!(cid = %&cid[..12], "skip (server has it)");
116	                continue;
117	            }
118	            let range = by_cid[cid];
119	            server.put(cid, &bytes[range.start..range.end]).await?;
120	            chunks_uploaded += 1;
121	            bytes_uploaded += range.len() as u64;
122	            tracing::debug!(cid = %&cid[..12], len = range.len(), "uploaded");
123	        }
124	        tracing::debug!(path = %path, size = entry.size, chunks = entry.chunks.len(), "file done");
125	    }
126	
127	    // 5. Upload the fs-manifest blob itself (unless an identical tree was
128	    // already backed up and the server holds it).
129	    if want_cids.contains(fs_manifest_cid.as_str()) {
130	        server.put(&fs_manifest_cid, &manifest_bytes).await?;
131	        bytes_uploaded += manifest_bytes.len() as u64;
132	        tracing::debug!(cid = %&fs_manifest_cid[..12], len = manifest_bytes.len(), "fs-manifest uploaded");
133	    }
134	
135	    // 6. Commit the keep-set at last+1 (seq 1 on a cold namespace). A stale
136	    // seq is surfaced, never retried — one device cannot race itself (OQ5).
137	    let seq = server.current_seq().await?.map_or(1, |s| s + 1);
138	    server.commit_keep_set(&needed, seq).await?;
139	
140	    let report = BackupReport {
141	        files: manifest.entries.len() as u64,
142	        chunks_total,
143	        chunks_uploaded,
144	        bytes_uploaded,
145	        fs_manifest_cid,
146	        manifest_seq: seq,
147	    };
148	    tracing::info!(
149	        files = report.files,
150	        chunks_total = report.chunks_total,
151	        chunks_uploaded = report.chunks_uploaded,
152	        bytes_uploaded = report.bytes_uploaded,
153	        seq = report.manifest_seq,
154	        fs_manifest = %&report.fs_manifest_cid[..12],
155	        "backup committed"
156	    );
157	    Ok(report)
158	}

