35	    /// be created.
36	    pub fn open<P: AsRef<Path>>(dir: P, budget: u64) -> Result<Self, SyncError> {
37	        let dir = dir.as_ref().to_path_buf();
38	        fs::create_dir_all(&dir).map_err(|e| SyncError::Io { path: dir.clone(), source: e })?;
39	        let conn = Connection::open(dir.join("cache.sqlite"))?;
40	        conn.execute_batch(
41	            "CREATE TABLE IF NOT EXISTS chunks (
42	                 cid        TEXT PRIMARY KEY,
43	                 size       INTEGER NOT NULL,
44	                 access_seq INTEGER NOT NULL,
45	                 pinned     INTEGER NOT NULL DEFAULT 0
46	             );",
47	        )?;
48	        Ok(Self { dir, conn, budget })
49	    }
50	
51	    /// Where `cid`'s bytes live on disk (exposed for tests that corrupt it).
52	    #[must_use]
53	    pub fn blob_path(&self, cid_hex: &str) -> PathBuf {
