1	//! The customer's signed manifest: the list of what the provider is supposed to
2	//! be keeping. It is a sorted list of `(cid, size)` leaves, a Merkle root over
3	//! that list, a monotonic sequence number, and the customer's signature over a
4	//! **structured, domain-separated preimage** that binds all of it. Because the
5	//! customer signs it, "what we owe them" is in their handwriting; and because the
6	//! byte total and leaf count are bound into the signature, the storage bill
7	//! (byte-days) is a pure function of a document the customer authored, computable
8	//! without trusting the provider — and not forgeable after signing.
9	//!
10	//! Integrity properties (security review Phase 4):
11	//! - **I1** — `total_bytes` is bound into the signed preimage and re-derived from
12	//!   the leaves on verify, so it cannot be altered independently of the leaves.
13	//! - **I2** — the Merkle tree tags a single (odd) child distinctly from a pair, so
14	//!   `[A,B,C]` and `[A,B,C,C]` do not collide (CVE-2012-2459); duplicate cids are
15	//!   rejected outright.
16	//! - **I5** — a monotonic `seq` is bound in; a stale/replayed manifest is refused
17	//!   at the boundary.
18	//! - **I11** — the signature is over a versioned, domain-separated preimage, not a
19	//!   bare hash, so it cannot be confused with a receipt or ledger signature.
20	//! - **I12** — leaves are validated (hex content address, bounded size) and the
21	//!   wire form denies unknown fields.
22	
23	use std::collections::{BTreeMap, HashSet};
24	
25	use ed25519_dalek::VerifyingKey;
26	use serde::{Deserialize, Serialize};
27	
28	use crate::blobstore::MAX_OBJECT_BYTES;
29	use crate::crypto::{sha256_hex, verify_message, Keypair};
30	
31	/// The domain-separation tag + version for a manifest signature (I11).
32	const MANIFEST_SIG_DOMAIN: &str = "ciss/v1/manifest";
33	
34	/// A single manifest leaf: a fingerprint bound to its claimed size.
35	#[derive(Debug, Clone, Serialize, Deserialize)]
36	#[serde(deny_unknown_fields)]
37	pub struct ManifestLeaf {
38	    cid: String,
39	    size: usize,
40	}
41	
42	impl ManifestLeaf {
43	    /// Build a leaf from a content address and its claimed size.
44	    #[must_use]
45	    pub fn new(cid: &str, size: usize) -> Self {
46	        Self {
47	            cid: cid.to_owned(),
48	            size,
49	        }
50	    }
51	
52	    /// The content address.
53	    #[must_use]
54	    pub fn cid(&self) -> &str {
55	        &self.cid
56	    }
57	
58	    /// The claimed size in bytes.
59	    #[must_use]
60	    pub fn size(&self) -> usize {
61	        self.size
62	    }
63	
64	    /// Whether the leaf is well-formed: a 64-hex content address and a size within
65	    /// the per-object ceiling (I12).
66	    fn is_valid(&self) -> bool {
67	        let cid_ok = self.cid.len() == 64
68	            && self
69	                .cid
70	                .bytes()
71	                .all(|b| b.is_ascii_digit() || (b'a'..=b'f').contains(&b));
72	        cid_ok && self.size as u64 <= MAX_OBJECT_BYTES
73	    }
74	}
75	
76	/// Hash of a single leaf: binds the fingerprint to its claimed size.
77	fn leaf_hash(leaf: &ManifestLeaf) -> String {
78	    sha256_hex(format!("leaf:{}:{}", leaf.cid, leaf.size).as_bytes())
79	}
80	
81	/// Merkle root over the leaf set (canonical: leaves are sorted by cid, so the
82	/// root is a pure function of the set). An odd child is tagged **distinctly** from
83	/// a pair (`node1:` vs `node:`), so a duplicate-last padding cannot make two
84	/// different leaf sets collide (I2).
85	#[must_use]
