            kind: DEVICE_HEAD_KIND.to_owned(),
            device_id: device_id.to_owned(),
            counter,
            fs_root: fs_root.to_owned(),
            parent,
            base,
            signature,
        }
    }

    /// Canonical DAG-CBOR bytes (the content-addressed wire form).
    ///
    /// # Errors
    ///
    /// [`SyncError::Encode`] on serializer failure.
