    // seq is surfaced, never retried — one device cannot race itself (OQ5).
    let seq = server.current_seq().await?.map_or(1, |s| s + 1);
    server.commit_keep_set(&pushed.needed, seq).await?;

    let report = BackupReport {
        files: pushed.files,
