1	//! The frontier commit: publish this device's tree as a signed `DeviceHead`
2	//! and fold it into the shared `Frontier.heads` map, non-lossily.
3	//!
4	//! Slot discipline makes concurrency safe: a device writes only
5	//! `heads[its own device_id]`; a stale-seq refusal (I5) means another device
6	//! landed first, so the loop re-reads the frontier, re-applies its own slot
7	//! onto the fresh heads, recomputes the keep-set, and retries (bounded).
8	//! The keep-set it commits covers **every** head's closure — `DeviceHead`
9	//! blobs, fs-manifests, all chunks, and base manifests — never just its own
10	//! tree: a commit that listed only its own closure would orphan the other
11	//! device's bytes (the M3 no-data-loss invariant).
12	
13	use std::collections::BTreeMap;
14	use std::path::Path;
15	
16	use crate::backup::push_tree;
17	use crate::device_head::DeviceHead;
18	use crate::error::SyncError;
19	use crate::manifest::{DagCbor, ManifestCodec};
20	use crate::state::SyncState;
21	use crate::transport::{AccountKey, BlobTransport, FrontierView, ManifestSlot};
22	
23	const MAX_COMMIT_RETRIES: u32 = 3;
24	const KEY_COUNTER: &str = "device_counter";
25	const KEY_LAST_HEAD: &str = "last_head_cid";
26	const KEY_BASE: &str = "base_fs_root";
27	
28	/// What a frontier backup did.
29	#[derive(Debug, Clone)]
30	pub struct FrontierReport {
31	    /// Files in this device's logical tree.
32	    pub files: u64,
33	    /// Distinct chunks the tree references.
34	    pub chunks_total: u64,
35	    /// Chunks actually transferred.
36	    pub chunks_uploaded: u64,
37	    /// Bytes actually transferred.
38	    pub bytes_uploaded: u64,
39	    /// This device's fs-manifest cid.
40	    pub fs_manifest_cid: String,
41	    /// The seq the frontier committed at.
42	    pub manifest_seq: u64,
43	    /// The cid of the `DeviceHead` this backup published.
44	    pub device_head_cid: String,
45	    /// Stale-seq retries the commit needed (0 = landed first try).
46	    pub commit_retries: u32,
47	}
48	
49	/// This device's persisted frontier state (counter/parent/base).
50	fn read_chain(state: &SyncState) -> Result<(u64, Option<String>, Option<String>), SyncError> {
51	    let counter = state
52	        .config_get(KEY_COUNTER)?
53	        .map(|v| v.parse::<u64>().map_err(|e| SyncError::Decode(format!("device_counter: {e}"))))
54	        .transpose()?
55	        .unwrap_or(0);
56	    Ok((counter, state.config_get(KEY_LAST_HEAD)?, state.config_get(KEY_BASE)?))
57	}
58	
59	/// Add every blob of `head`'s closure (head blob + fs-manifest + chunks +
60	/// base manifest) into `leaves`, fetching what sizes require. The head is
61	/// verified before anything of it is trusted.
62	async fn extend_with_head_closure<S: BlobTransport + Sync>(
63	    server: &S,
64	    verifier: &ed25519_dalek::VerifyingKey,
65	    head_cid: &str,
66	    leaves: &mut BTreeMap<String, u64>,
67	) -> Result<(), SyncError> {
68	    let head_bytes = server.get(head_cid).await?;
69	    let head = DeviceHead::decode_verified(&head_bytes, verifier)?;
70	    leaves.insert(head_cid.to_owned(), head_bytes.len() as u64);
71	
72	    let manifest_bytes = server.get(&head.fs_root).await?;
73	    let manifest = DagCbor.decode(&manifest_bytes)?;
74	    leaves.insert(head.fs_root.clone(), manifest_bytes.len() as u64);
75	    for entry in manifest.entries.values() {
76	        for chunk in &entry.chunks {
77	            leaves.insert(chunk.sha256_hex(), u64::from(chunk.len));
78	        }
79	    }
80	    if let Some(base) = &head.base {
81	        if !leaves.contains_key(base) {
82	            let base_bytes = server.get(base).await?;
83	            leaves.insert(base.clone(), base_bytes.len() as u64);
84	        }
85	    }
86	    Ok(())
87	}
88	
89	/// Publish `dir` as this device's head and commit the frontier, non-lossily.
90	///
91	/// # Errors
92	///
93	/// Push/transport failures; a commit that stays stale past the retry bound
94	/// surfaces the final [`SyncError::StaleSeq`].
95	pub async fn backup_frontier<S>(
96	    dir: &Path,
97	    server: &S,
98	    state: &mut SyncState,
99	    device_id: &str,
100	) -> Result<FrontierReport, SyncError>
101	where
102	    S: BlobTransport + ManifestSlot + AccountKey + Sync,
103	{
104	    // 1. Push this device's tree (chunks + fs-manifest; have/want inside).
105	    let pushed = push_tree(dir, server, Some(state)).await?;
106	
107	    // 2. Build + upload this commit's DeviceHead (once — the head does not
108	    // depend on the frontier it lands into; only the heads map does).
109	    let (counter, parent, base) = read_chain(state)?;
110	    let head = DeviceHead::new_signed(
111	        device_id,
112	        counter + 1,
113	        &pushed.fs_manifest_cid,
114	        parent,
115	        base,
116	        server.keypair(),
117	    );
118	    let head_bytes = head.encode()?;
119	    let head_cid = {
120	        use sha2::Digest as _;
121	        let digest: [u8; 32] = sha2::Sha256::digest(&head_bytes).into();
122	        crate::chunk::Hash32(digest).to_hex()
123	    };
124	    server.put(&head_cid, &head_bytes).await?;
125	
126	    // 3. The commit loop: read the frontier, apply only our slot, cover every
127	    // head's closure in the keep-set, and retry on a stale seq.
128	    let verifier = server.keypair().verifying_key();
129	    let mut retries = 0u32;
130	    loop {
131	        let frontier = server.frontier().await?;
132	        let (seq, mut heads) = match &frontier {
133	            Some(FrontierView { seq, heads, .. }) => (seq + 1, heads.clone()),
134	            None => (1, BTreeMap::new()),
135	        };
136	        heads.insert(device_id.to_owned(), head_cid.clone());
137	
138	        let mut leaves: BTreeMap<String, u64> =
139	            pushed.needed.iter().cloned().collect();
140	        leaves.insert(head_cid.clone(), head_bytes.len() as u64);
141	        for (other_id, other_cid) in &heads {
142	            if other_id == device_id {
143	                continue;
144	            }
145	            extend_with_head_closure(server, &verifier, other_cid, &mut leaves).await?;
146	        }
147	        let leaves: Vec<(String, u64)> = leaves.into_iter().collect();
148	
149	        tracing::info!(
150	            seq,
151	            heads = heads.len(),
152	            leaves = leaves.len(),
153	            retries,
154	            "committing frontier"
155	        );
156	        match server.commit_frontier(&leaves, seq, &heads).await {
157	            Ok(()) => {
158	                state.config_set(KEY_COUNTER, &(counter + 1).to_string())?;
159	                state.config_set(KEY_LAST_HEAD, &head_cid)?;
160	                return Ok(FrontierReport {
161	                    files: pushed.files,
162	                    chunks_total: pushed.chunks_total,
163	                    chunks_uploaded: pushed.chunks_uploaded,
164	                    bytes_uploaded: pushed.bytes_uploaded,
165	                    fs_manifest_cid: pushed.fs_manifest_cid,
166	                    manifest_seq: seq,
167	                    device_head_cid: head_cid,
168	                    commit_retries: retries,
169	                });
170	            }
171	            Err(SyncError::StaleSeq { attempted }) if retries < MAX_COMMIT_RETRIES => {
172	                retries += 1;
173	                tracing::info!(attempted, retries, "stale seq — re-reading the frontier");
174	            }
175	            Err(e) => return Err(e),
176	        }
177	    }
178	}

1	//! The customer's signed manifest: the list of what the provider is supposed to
2	//! be keeping. It is a sorted list of `(cid, size)` leaves, a Merkle root over
3	//! that list, a monotonic sequence number, and the customer's signature over a
4	//! **structured, domain-separated preimage** that binds all of it. Because the
5	//! customer signs it, "what we owe them" is in their handwriting; and because the
6	//! byte total and leaf count are bound into the signature, the storage bill
7	//! (byte-days) is a pure function of a document the customer authored, computable
8	//! without trusting the provider — and not forgeable after signing.
9	//!
10	//! Integrity properties (security review Phase 4):
11	//! - **I1** — `total_bytes` is bound into the signed preimage and re-derived from
12	//!   the leaves on verify, so it cannot be altered independently of the leaves.
13	//! - **I2** — the Merkle tree tags a single (odd) child distinctly from a pair, so
14	//!   `[A,B,C]` and `[A,B,C,C]` do not collide (CVE-2012-2459); duplicate cids are
15	//!   rejected outright.
16	//! - **I5** — a monotonic `seq` is bound in; a stale/replayed manifest is refused
17	//!   at the boundary.
18	//! - **I11** — the signature is over a versioned, domain-separated preimage, not a
19	//!   bare hash, so it cannot be confused with a receipt or ledger signature.
20	//! - **I12** — leaves are validated (hex content address, bounded size) and the
21	//!   wire form denies unknown fields.
22	
23	use std::collections::{BTreeMap, HashSet};
24	
25	use ed25519_dalek::VerifyingKey;
26	use serde::{Deserialize, Serialize};
27	
28	use crate::blobstore::MAX_OBJECT_BYTES;
29	use crate::crypto::{sha256_hex, verify_message, Keypair};
30	
31	/// The domain-separation tag + version for a manifest signature (I11).
32	const MANIFEST_SIG_DOMAIN: &str = "ciss/v1/manifest";
33	
34	/// A single manifest leaf: a fingerprint bound to its claimed size.
35	#[derive(Debug, Clone, Serialize, Deserialize)]
36	#[serde(deny_unknown_fields)]
37	pub struct ManifestLeaf {
38	    cid: String,
39	    size: usize,
40	}
41	
42	impl ManifestLeaf {
43	    /// Build a leaf from a content address and its claimed size.
44	    #[must_use]
45	    pub fn new(cid: &str, size: usize) -> Self {
46	        Self {
47	            cid: cid.to_owned(),
48	            size,
49	        }
50	    }
51	
52	    /// The content address.
53	    #[must_use]
54	    pub fn cid(&self) -> &str {
55	        &self.cid
56	    }
57	
58	    /// The claimed size in bytes.
59	    #[must_use]
60	    pub fn size(&self) -> usize {
61	        self.size
62	    }
63	
64	    /// Whether the leaf is well-formed: a 64-hex content address and a size within
65	    /// the per-object ceiling (I12).
66	    fn is_valid(&self) -> bool {
67	        let cid_ok = self.cid.len() == 64
68	            && self
69	                .cid
70	                .bytes()
71	                .all(|b| b.is_ascii_digit() || (b'a'..=b'f').contains(&b));
72	        cid_ok && self.size as u64 <= MAX_OBJECT_BYTES
73	    }
74	}
75	
76	/// Hash of a single leaf: binds the fingerprint to its claimed size.
77	fn leaf_hash(leaf: &ManifestLeaf) -> String {
78	    sha256_hex(format!("leaf:{}:{}", leaf.cid, leaf.size).as_bytes())
79	}
80	
81	/// Merkle root over the leaf set (canonical: leaves are sorted by cid, so the
82	/// root is a pure function of the set). An odd child is tagged **distinctly** from
83	/// a pair (`node1:` vs `node:`), so a duplicate-last padding cannot make two
84	/// different leaf sets collide (I2).
85	#[must_use]
86	pub fn merkle_root(leaves: &[ManifestLeaf]) -> String {
87	    if leaves.is_empty() {
88	        return sha256_hex(b"empty-manifest");
89	    }
90	    let mut ordered = leaves.to_vec();
91	    ordered.sort_by(|a, b| a.cid.cmp(&b.cid));
92	    let mut level: Vec<String> = ordered.iter().map(leaf_hash).collect();
93	    while level.len() > 1 {
94	        level = level
95	            .chunks(2)
96	            .map(|pair| match pair.get(1) {
97	                Some(right) => sha256_hex(format!("node:{}:{right}", pair[0]).as_bytes()),
98	                None => sha256_hex(format!("node1:{}", pair[0]).as_bytes()),
99	            })
100	            .collect();
101	    }
102	    level.into_iter().next().unwrap_or_default()
103	}
104	
105	/// Whether the leaf set contains the same cid more than once (an inflation vector
106	/// even with the padding fix — rejected on verify, I2).
107	fn has_duplicate_cids(leaves: &[ManifestLeaf]) -> bool {
108	    let mut seen = HashSet::new();
109	    leaves.iter().any(|leaf| !seen.insert(leaf.cid.as_str()))
110	}
111	
112	/// The domain-separated preimage the customer signs. Binds the signer, the
113	/// sequence number, the leaf count, the byte total, the root — and, when
114	/// present, the `heads` map (M3 frontier) — so none can be altered without
115	/// invalidating the signature (I1, I5, I11; B1 extended).
116	///
117	/// Back-compat is structural: with `heads = None` the preimage is
118	/// byte-identical to the pre-heads era, so every manifest signed before the
119	/// field existed still verifies. A present-but-tampered map changes the
120	/// digest; a stripped map falls back to the legacy preimage, which the
121	/// original signature (bound to the digest) no longer matches.
122	fn signing_preimage(
123	    signer_id: &str,
124	    seq: u64,
125	    leaf_count: usize,
126	    total_bytes: usize,
127	    root: &str,
128	    heads: Option<&BTreeMap<String, String>>,
129	) -> String {
130	    let base = format!("{MANIFEST_SIG_DOMAIN}:{signer_id}:{seq}:{leaf_count}:{total_bytes}:{root}");
131	    match heads {
132	        None => base,
133	        Some(map) => {
134	            // BTreeMap iteration is key-sorted, so the digest is canonical.
135	            let joined = map.iter().fold(String::new(), |mut acc, (device, cid)| {
136	                use std::fmt::Write as _;
137	                write!(acc, "{device}={cid};").expect("writing to a String cannot fail");
138	                acc
139	            });
140	            format!("{base}:heads={}", sha256_hex(joined.as_bytes()))
141	        }
142	    }
143	}
144	
145	/// A built, signed manifest.
146	#[derive(Debug, Clone, Serialize, Deserialize)]
147	#[serde(deny_unknown_fields)]
148	pub struct Manifest {
149	    leaves: Vec<ManifestLeaf>,
150	    root: String,
151	    total_bytes: usize,
152	    signer_id: String,
153	    seq: u64,
154	    signature: String,
155	    /// The M3 frontier: `device_id → cid(DeviceHead)`, owner-signed via the
156	    /// preimage, opaque to the server. Absent for pre-frontier manifests and
157	    /// omitted from the wire when absent.
158	    #[serde(default, skip_serializing_if = "Option::is_none")]
159	    heads: Option<BTreeMap<String, String>>,
160	}
161	
162	impl Manifest {
163	    /// The Merkle root the customer signed.
164	    #[must_use]
165	    pub fn root(&self) -> &str {
166	        &self.root
167	    }
168	
169	    /// Total bytes at rest implied by the list — the rent base.
170	    #[must_use]
171	    pub fn total_bytes(&self) -> usize {
172	        self.total_bytes
173	    }
174	
175	    /// The customer identifier that authored/signed the manifest.
176	    #[must_use]
177	    pub fn signer_id(&self) -> &str {
178	        &self.signer_id
179	    }
180	
181	    /// The monotonic sequence number (replay/rollback protection).
182	    #[must_use]
183	    pub fn seq(&self) -> u64 {
184	        self.seq
185	    }
186	
187	    /// The sorted leaves.
188	    #[must_use]
189	    pub fn leaves(&self) -> &[ManifestLeaf] {
190	        &self.leaves
191	    }
192	
193	    /// The frontier heads (`device_id → cid(DeviceHead)`), if this manifest
194	    /// carries any. Signature-bound; the server never interprets them.
195	    #[must_use]
196	    pub fn heads(&self) -> Option<&BTreeMap<String, String>> {
