//! Workflow tier — the M1 capability gate: back up a tree, wipe local state,
//! `sync restore` reproduces it byte-identically; a tampered chunk is refused,
//! never written; a cold restore (zero local state) discovers the fs-manifest
//! from the keep-set alone.

mod common;

use std::collections::HashSet;
use std::fs;
use std::os::unix::fs::PermissionsExt;

use ciss_cli::client::Client;
use ciss_cli::sync::HttpCiss;
use ciss_sync::{backup, restore, BlobTransport, ManifestSlot, SyncError};
use common::World;

fn build_tree(root: &std::path::Path) {
    fs::create_dir_all(root.join("docs/nested")).expect("mkdir");
    fs::write(root.join("hello.txt"), b"round trip").expect("write");
    fs::write(root.join("docs/tiny.md"), b"x").expect("write");
    let big: Vec<u8> = (0..2 * 1024 * 1024 + 777).map(|i| (i % 241) as u8).collect();
    fs::write(root.join("docs/nested/big.bin"), big).expect("write");
    let script = root.join("run.sh");
    fs::write(&script, b"#!/bin/sh\necho hi\n").expect("write");
    fs::set_permissions(&script, fs::Permissions::from_mode(0o755)).expect("chmod");
}

fn syncer(world: &World, name: &str) -> HttpCiss {
    let keypair = ciss::crypto::derive_keypair("flow-master", name);
    HttpCiss::new(Client::new(world.url("")), keypair)
}

/// Walk `dir` into (relative path → (bytes, mode, mtime_secs)).
fn snapshot(dir: &std::path::Path) -> std::collections::BTreeMap<String, (Vec<u8>, u32, i64)> {
    fn walk(
        root: &std::path::Path,
        dir: &std::path::Path,
        out: &mut std::collections::BTreeMap<String, (Vec<u8>, u32, i64)>,
    ) {
        for entry in fs::read_dir(dir).expect("read_dir") {
            let entry = entry.expect("entry");
            let path = entry.path();
            if path.is_dir() {
                walk(root, &path, out);
            } else {
                let rel = path.strip_prefix(root).expect("rel").to_str().expect("utf8").to_owned();
                let meta = entry.metadata().expect("meta");
                let mtime = meta
                    .modified()
                    .expect("mtime")
                    .duration_since(std::time::UNIX_EPOCH)
                    .expect("post-epoch")
                    .as_secs();
                out.insert(
                    rel,
                    (
                        fs::read(&path).expect("read"),
                        meta.permissions().mode() & 0o7777,
                        i64::try_from(mtime).expect("fits"),
                    ),
                );
            }
        }
    }
    let mut out = std::collections::BTreeMap::new();
    walk(dir, dir, &mut out);
    out
}

/// The end-to-end M1 gate: backup → wipe → restore → byte-identical
/// (content + mode; mtime restored to the second).
#[tokio::test]
async fn backup_wipe_restore_is_byte_identical() {
    let world = World::spawn().await;
    let server = syncer(&world, "roundtripper");
    let src = tempfile::tempdir().expect("tempdir");
    build_tree(src.path());
    let before = snapshot(src.path());

    let b = backup(src.path(), &server, None).await.expect("backup");

    // "Wipe local": restore into a fresh directory, using only the manifest cid.
    let dst = tempfile::tempdir().expect("tempdir");
    let r = restore(dst.path(), &server, Some(&b.fs_manifest_cid)).await.expect("restore");
    assert_eq!(r.files, b.files);
    assert_eq!(r.fs_manifest_cid, b.fs_manifest_cid);

    let after = snapshot(dst.path());
    assert_eq!(
        before.keys().collect::<Vec<_>>(),
        after.keys().collect::<Vec<_>>(),
        "the restored tree must have exactly the backed-up paths"
    );
    for (path, (bytes, mode, mtime)) in &before {
        let (r_bytes, r_mode, r_mtime) = &after[path];
        assert_eq!(r_bytes, bytes, "{path}: bytes must be identical");
        assert_eq!(r_mode, mode, "{path}: mode must be restored");
        assert_eq!(r_mtime, mtime, "{path}: mtime must be restored (second precision)");
    }

    world.shutdown().await;
}

/// A transport that substitutes one chunk's bytes — the engine must fail
/// closed on its own verification: the error names the cid, and the
/// destination file is never written (no partial/poisoned output).
struct Substituting<'a> {
    inner: &'a HttpCiss,
    target_cid: String,
}

#[async_trait::async_trait]
impl BlobTransport for Substituting<'_> {
    async fn have(&self) -> Result<HashSet<String>, SyncError> {
        self.inner.have().await
    }
    async fn put(&self, cid_hex: &str, bytes: &[u8]) -> Result<(), SyncError> {
        self.inner.put(cid_hex, bytes).await
    }
    async fn get(&self, cid_hex: &str) -> Result<Vec<u8>, SyncError> {
        if cid_hex == self.target_cid {
            return Ok(b"substituted bytes, wrong hash".to_vec());
        }
        self.inner.get(cid_hex).await
    }
}

#[async_trait::async_trait]
impl ManifestSlot for Substituting<'_> {
    async fn current_seq(&self) -> Result<Option<u64>, SyncError> {
        self.inner.current_seq().await
    }
    async fn keep_set(&self) -> Result<Option<Vec<(String, u64)>>, SyncError> {
        self.inner.keep_set().await
    }
    async fn frontier(&self) -> Result<Option<ciss_sync::FrontierView>, SyncError> {
        self.inner.frontier().await
    }
    async fn commit_keep_set(
        &self,
        leaves: &[(String, u64)],
        seq: u64,
    ) -> Result<(), SyncError> {
        self.inner.commit_keep_set(leaves, seq).await
    }
    async fn commit_frontier(
        &self,
        leaves: &[(String, u64)],
        seq: u64,
        heads: &std::collections::BTreeMap<String, String>,
    ) -> Result<(), SyncError> {
        self.inner.commit_frontier(leaves, seq, heads).await
    }
}

#[tokio::test]
async fn tampered_chunk_rejected_and_nothing_written() {
    let world = World::spawn().await;
    let server = syncer(&world, "tamper-victim");
    let src = tempfile::tempdir().expect("tempdir");
    fs::write(src.path().join("precious.txt"), b"the only file").expect("write");
    let b = backup(src.path(), &server, None).await.expect("backup");

    // The one chunk of the one file is the substitution target.
    let keep = server.keep_set().await.expect("keep").expect("exists");
    let target_cid = keep
        .iter()
        .map(|(c, _)| c.clone())
        .find(|c| c != &b.fs_manifest_cid)
        .expect("the file's chunk is in the keep-set");

    let lying = Substituting { inner: &server, target_cid: target_cid.clone() };
    let dst = tempfile::tempdir().expect("tempdir");
    let err = restore(dst.path(), &lying, Some(&b.fs_manifest_cid))
        .await
        .expect_err("substituted bytes must fail the restore");
    let msg = err.to_string();
    assert!(msg.contains(&target_cid[..12]), "the error names the cid: {msg}");
    assert!(
        !dst.path().join("precious.txt").exists(),
        "a tampered chunk must not leave a file behind (fail closed)"
    );

    world.shutdown().await;
}

/// Cold restore: zero local state — not even the fs-manifest cid. The keep-set
/// scan finds the self-tagged manifest among many small non-manifest leaves.
#[tokio::test]
async fn cold_restore_discovers_the_fs_manifest() {
    let world = World::spawn().await;
    let server = syncer(&world, "cold-restorer");
    let src = tempfile::tempdir().expect("tempdir");
    // Many tiny files: the keep-set fills with small non-manifest leaves, so
    // discovery must reject decoy candidates by the kind tag, not by size.
    for i in 0..8 {
        fs::write(src.path().join(format!("tiny-{i}.txt")), format!("tiny {i}")).expect("write");
    }
    let b = backup(src.path(), &server, None).await.expect("backup");
    let before = snapshot(src.path());

    let dst = tempfile::tempdir().expect("tempdir");
    let r = restore(dst.path(), &server, None).await.expect("cold restore");
    assert_eq!(r.fs_manifest_cid, b.fs_manifest_cid, "discovery must find the real manifest");

    let after = snapshot(dst.path());
    assert_eq!(before.len(), after.len());
    for (path, (bytes, ..)) in &before {
        assert_eq!(&after[path].0, bytes, "{path}: restored bytes identical");
    }

    world.shutdown().await;
}

//! Workflow tier — the M3 capability gate: two devices converge to the SAME
//! tree, deterministically and clock-free; a real conflict is preserved as a
//! conflict-copy on both devices, never lost; a rename transfers zero chunks
//! (dedup carries it — no detection machinery needed).

mod common;

use std::fs;

use ciss_cli::client::Client;
use ciss_cli::sync::HttpCiss;
use ciss_sync::{backup_frontier, converge, scan_tree, SyncState};
use common::World;

fn syncer(world: &World) -> HttpCiss {
    let keypair = ciss::crypto::derive_keypair("flow-master", "converge-pool");
    HttpCiss::new(Client::new(world.url("")), keypair)
}

struct Device {
    dir: tempfile::TempDir,
    state: SyncState,
    id: &'static str,
    _home: tempfile::TempDir,
}

fn device(id: &'static str) -> Device {
    let dir = tempfile::tempdir().expect("tempdir");
    let home = tempfile::tempdir().expect("tempdir");
    let state = SyncState::open(home.path().join("s")).expect("state");
    Device { dir, state, id, _home: home }
}

/// Both trees byte-identical? Compare the deterministic scan content ids.
fn assert_converged(a: &Device, b: &Device) {
    let ma = scan_tree(a.dir.path()).expect("scan a");
    let mb = scan_tree(b.dir.path()).expect("scan b");
    assert_eq!(
        ma.entries.keys().collect::<Vec<_>>(),
        mb.entries.keys().collect::<Vec<_>>(),
        "same paths on both devices"
    );
    for (path, ea) in &ma.entries {
        let eb = &mb.entries[path];
        assert_eq!(ea.chunks, eb.chunks, "{path}: same content on both devices");
        assert_eq!(ea.size, eb.size);
    }
}

/// Disjoint edits merge cleanly: each device ends up with both files, and the
/// two trees are identical.
#[tokio::test]
async fn disjoint_edits_merge() {
    let world = World::spawn().await;
    let server = syncer(&world);
    let mut a = device("dev-a");
    let mut b = device("dev-b");
    fs::write(a.dir.path().join("alpha.txt"), b"from device a").expect("write");
    fs::write(b.dir.path().join("beta.txt"), vec![7u8; 200_000]).expect("write");

    backup_frontier(a.dir.path(), &server, &mut a.state, a.id).await.expect("a backup");
    backup_frontier(b.dir.path(), &server, &mut b.state, b.id).await.expect("b backup");

    let ra = converge(a.dir.path(), &mut a.state, &server, a.id).await.expect("a converge");
    assert!(ra.conflicts.is_empty(), "disjoint edits are not conflicts");
    assert!(a.dir.path().join("beta.txt").exists(), "A received B's file");

    let rb = converge(b.dir.path(), &mut b.state, &server, b.id).await.expect("b converge");
    assert!(rb.conflicts.is_empty());
    assert!(b.dir.path().join("alpha.txt").exists(), "B received A's file");

    assert_converged(&a, &b);
    world.shutdown().await;
}

/// Same-path divergence: the content-address winner keeps the path, the loser
/// is preserved as `<path>.conflict-<device>` — both contents on BOTH devices.
#[tokio::test]
async fn same_path_divergence_preserved() {
    let world = World::spawn().await;
    let server = syncer(&world);
    let mut a = device("dev-a");
    let mut b = device("dev-b");
    fs::write(a.dir.path().join("notes.txt"), b"device A's version").expect("write");
    fs::write(b.dir.path().join("notes.txt"), b"device B's very different take").expect("write");

    backup_frontier(a.dir.path(), &server, &mut a.state, a.id).await.expect("a backup");
    backup_frontier(b.dir.path(), &server, &mut b.state, b.id).await.expect("b backup");

    let ra = converge(a.dir.path(), &mut a.state, &server, a.id).await.expect("a converge");
    assert_eq!(ra.conflicts.len(), 1, "one real conflict surfaced");
    let rb = converge(b.dir.path(), &mut b.state, &server, b.id).await.expect("b converge");

    // Both devices hold both contents: the winner at notes.txt, the loser at
    // exactly one conflict path; the split is identical on both devices.
    for d in [&a, &b] {
        let main = fs::read(d.dir.path().join("notes.txt")).expect("read");
        let conflicts: Vec<_> = fs::read_dir(d.dir.path())
            .expect("dir")
            .filter_map(Result::ok)
            .map(|e| e.file_name().to_string_lossy().into_owned())
            .filter(|n| n.contains(".conflict-"))
            .collect();
        assert_eq!(conflicts.len(), 1, "exactly one conflict-copy on {}", d.id);
        let copy = fs::read(d.dir.path().join(&conflicts[0])).expect("read");
        let mut both = [main.clone(), copy];
        both.sort();
        assert_eq!(
            both,
            [b"device A's version".to_vec(), b"device B's very different take".to_vec()],
            "both contents preserved on {}",
            d.id
        );
    }
    assert_converged(&a, &b);
    let _ = rb;
    world.shutdown().await;
}

/// A rename is delete+add whose chunks the server already holds: the
/// re-backup transfers zero chunks (dedup — no detection machinery).
#[tokio::test]
async fn rename_transfers_zero_chunks() {
    let world = World::spawn().await;
    let server = syncer(&world);
    let mut a = device("dev-a");
    let payload: Vec<u8> = (0..600_000).map(|i| (i % 229) as u8).collect();
    fs::write(a.dir.path().join("old-name.bin"), &payload).expect("write");
    backup_frontier(a.dir.path(), &server, &mut a.state, a.id).await.expect("backup");

    fs::rename(a.dir.path().join("old-name.bin"), a.dir.path().join("new-name.bin"))
        .expect("rename");
    let r = backup_frontier(a.dir.path(), &server, &mut a.state, a.id).await.expect("rebackup");
    assert_eq!(r.chunks_uploaded, 0, "a rename moves no bytes — dedup carries it");

    world.shutdown().await;
}

/// Modify-vs-delete: the modification wins (non-lossy default).
#[tokio::test]
async fn modify_beats_delete() {
    let world = World::spawn().await;
    let server = syncer(&world);
    let mut a = device("dev-a");
    let mut b = device("dev-b");

    // A shared base: A creates the file, B receives it via converge.
    fs::write(a.dir.path().join("shared.txt"), b"the original").expect("write");
    backup_frontier(a.dir.path(), &server, &mut a.state, a.id).await.expect("a backup");
    backup_frontier(b.dir.path(), &server, &mut b.state, b.id).await.expect("b backup");
    converge(a.dir.path(), &mut a.state, &server, a.id).await.expect("a converge");
    converge(b.dir.path(), &mut b.state, &server, b.id).await.expect("b converge");
    assert!(b.dir.path().join("shared.txt").exists());

    // A deletes; B modifies. The modification survives on both.
    fs::remove_file(a.dir.path().join("shared.txt")).expect("rm");
    fs::write(b.dir.path().join("shared.txt"), b"B's improvement").expect("write");
    backup_frontier(a.dir.path(), &server, &mut a.state, a.id).await.expect("a backup 2");
    backup_frontier(b.dir.path(), &server, &mut b.state, b.id).await.expect("b backup 2");
    converge(a.dir.path(), &mut a.state, &server, a.id).await.expect("a converge 2");
    converge(b.dir.path(), &mut b.state, &server, b.id).await.expect("b converge 2");

    for d in [&a, &b] {
        assert_eq!(
            fs::read(d.dir.path().join("shared.txt")).expect("read"),
            b"B's improvement",
            "the modification wins over the delete on {}",
            d.id
        );
    }
    assert_converged(&a, &b);
    world.shutdown().await;
}

//! Workflow tier — `sync backup` (M1 Phase 2). One device pushes a tree to an
//! in-process CISS: only missing chunks transfer, the fs-manifest blob is
//! stored, and the keep-set Manifest advances under the I5 seq-CAS. This is
//! the phase's wiring test: it proves the engine reaches the real server
//! boundary, not just that the chunker works.

mod common;

use std::collections::HashSet;
use std::fs;
use std::sync::atomic::{AtomicU64, Ordering};

use ciss_cli::client::{self, Client};
use ciss_cli::sync::HttpCiss;
use ciss_sync::{backup, BlobTransport, DagCbor, ManifestCodec, ManifestSlot, SyncError};
use common::World;

fn build_tree(root: &std::path::Path) {
    fs::create_dir_all(root.join("sub")).expect("mkdir");
    fs::write(root.join("small.txt"), b"hello sync").expect("write");
    let big: Vec<u8> = (0..2 * 1024 * 1024 + 999).map(|i| (i % 249) as u8).collect();
    fs::write(root.join("sub/big.bin"), big).expect("write");
}

fn syncer(world: &World) -> HttpCiss {
    let keypair = ciss::crypto::derive_keypair("flow-master", "syncer");
    HttpCiss::new(Client::new(world.url("")), keypair)
}

/// The core backup story: first push uploads everything + the fs-manifest and
/// commits keep-set seq 1; an unchanged re-push uploads **zero** chunks
/// (have/want skip) and the keep-set still advances strictly (I5).
#[tokio::test]
async fn backup_uploads_once_then_skips_and_keep_set_advances_under_i5() {
    let world = World::spawn().await;
    let server = syncer(&world);
    let dir = tempfile::tempdir().expect("tempdir");
    build_tree(dir.path());

    // First backup: everything transfers.
    let r1 = backup(dir.path(), &server, None).await.expect("backup 1");
    assert_eq!(r1.files, 2);
    assert!(r1.chunks_total >= 3, "the 2 MiB file must chunk (got {})", r1.chunks_total);
    assert_eq!(r1.chunks_uploaded, r1.chunks_total, "cold server: all chunks upload");
    assert_eq!(r1.manifest_seq, 1, "the first keep-set commit is seq 1");

    // The fs-manifest blob is stored and decodes back to a manifest whose
    // content_id is the stored cid (the address is the server's own sha-256).
    let keypair = ciss::crypto::derive_keypair("flow-master", "syncer");
    let session = client::session_for(&keypair);
    let fetched = server
        .client()
        .get_s3(Some(&session), &session.did, &r1.fs_manifest_cid)
        .await
        .expect("fs-manifest stored");
    let decoded = DagCbor.decode(&fetched.bytes).expect("decode fs-manifest");
    assert_eq!(decoded.content_id().expect("cid"), r1.fs_manifest_cid);
    assert_eq!(decoded.entries.len(), 2);

    // The keep-set Manifest names every chunk cid + the fs-manifest cid.
    let keep = server
        .client()
        .get_manifest(&session.did)
        .await
        .expect("get_manifest")
        .expect("a keep-set exists after backup");
    assert_eq!(keep.seq(), 1);
    let leaf_cids: HashSet<&str> = keep.leaves().iter().map(|l| l.cid()).collect();
    assert!(leaf_cids.contains(r1.fs_manifest_cid.as_str()));
    for entry in decoded.entries.values() {
        for c in &entry.chunks {
            assert!(leaf_cids.contains(c.sha256_hex().as_str()), "keep-set must hold every chunk");
        }
    }

    // Unchanged re-push: zero chunks move, seq still strictly advances.
    let r2 = backup(dir.path(), &server, None).await.expect("backup 2");
    assert_eq!(r2.chunks_uploaded, 0, "have/want must skip everything");
    assert_eq!(r2.bytes_uploaded, 0);
    assert_eq!(r2.manifest_seq, 2, "keep-set commits are strictly newer (I5)");

    // I5 guard: a stale/equal-seq commit is refused by the server and surfaced
    // as an error, never swallowed.
    let stale = ciss::manifest::build_manifest(
        &[ciss::manifest::ManifestLeaf::new(&r1.fs_manifest_cid, 1)],
        &session.did,
        &keypair,
        2, // equal to the stored seq — I5 demands strictly newer
    );
    let err = server
        .client()
        .put_manifest(&session, &stale)
        .await
        .expect_err("an equal-seq manifest must be refused");
    assert!(err.to_string().contains("seq"), "the error names the seq conflict: {err}");

    world.shutdown().await;
}

/// A transport that fails after `allow` puts — the "network died mid-backup"
/// story. The re-run must transfer only what is still missing (chunk-level
/// resume replaces byte-range resume).
struct FailAfter<'a> {
    inner: &'a HttpCiss,
    allow: u64,
    puts: AtomicU64,
}

#[async_trait::async_trait]
impl BlobTransport for FailAfter<'_> {
    async fn have(&self) -> Result<HashSet<String>, SyncError> {
        self.inner.have().await
    }
    async fn put(&self, cid_hex: &str, bytes: &[u8]) -> Result<(), SyncError> {
        if self.puts.fetch_add(1, Ordering::SeqCst) >= self.allow {
            return Err(SyncError::Transport("injected: connection lost".to_owned()));
        }
        self.inner.put(cid_hex, bytes).await
    }
    async fn get(&self, cid_hex: &str) -> Result<Vec<u8>, SyncError> {
        self.inner.get(cid_hex).await
    }
}

#[async_trait::async_trait]
impl ManifestSlot for FailAfter<'_> {
    async fn current_seq(&self) -> Result<Option<u64>, SyncError> {
        self.inner.current_seq().await
    }
    async fn keep_set(&self) -> Result<Option<Vec<(String, u64)>>, SyncError> {
        self.inner.keep_set().await
    }
    async fn frontier(&self) -> Result<Option<ciss_sync::FrontierView>, SyncError> {
        self.inner.frontier().await
    }
    async fn commit_keep_set(
        &self,
        leaves: &[(String, u64)],
        seq: u64,
    ) -> Result<(), SyncError> {
        self.inner.commit_keep_set(leaves, seq).await
    }
    async fn commit_frontier(
        &self,
        leaves: &[(String, u64)],
        seq: u64,
        heads: &std::collections::BTreeMap<String, String>,
    ) -> Result<(), SyncError> {
        self.inner.commit_frontier(leaves, seq, heads).await
    }
}

#[tokio::test]
async fn interrupted_backup_resumes_by_skipping_stored_chunks() {
    let world = World::spawn().await;
    let server = syncer(&world);
    let dir = tempfile::tempdir().expect("tempdir");
    build_tree(dir.path());

    // Fail after 2 chunk uploads: the backup must error (fail loud, no
    // partial keep-set commit pretending success).
    let flaky = FailAfter { inner: &server, allow: 2, puts: AtomicU64::new(0) };
    let err = backup(dir.path(), &flaky, None).await.expect_err("must fail mid-transfer");
    assert!(err.to_string().contains("connection lost"), "surfaced: {err}");
    let keypair = ciss::crypto::derive_keypair("flow-master", "syncer");
    let session = client::session_for(&keypair);
    assert!(
        server.client().get_manifest(&session.did).await.expect("get").is_none(),
        "an interrupted backup must not commit a keep-set"
    );

    // The re-run transfers only the chunks the server still lacks.
    let resumed = backup(dir.path(), &server, None).await.expect("resume");
    assert!(
        resumed.chunks_uploaded < resumed.chunks_total,
        "resume must skip the {} chunks that already landed",
        2
    );
    assert_eq!(resumed.manifest_seq, 1, "the first successful commit is seq 1");

    world.shutdown().await;
}

