//! Probe: two iroh endpoints in one process, no relay; A serves a blob via
//! BlobsProtocol, B downloads it by blake3 hash and proves byte + sha256
//! identity. This pins the exact API surface M4's IrohTransport will use.

use std::net::{Ipv4Addr, SocketAddrV4};

use iroh::{address_lookup::memory::MemoryLookup, endpoint::presets, Endpoint, RelayMode};
use iroh_blobs::{store::mem::MemStore, BlobsProtocol, Hash};
use sha2::Digest;

async fn endpoint(lookup: MemoryLookup) -> anyhow::Result<Endpoint> {
    let ep = Endpoint::builder(presets::Empty)
        .address_lookup(lookup)
        .relay_mode(RelayMode::Disabled)
        .bind_addr(SocketAddrV4::new(Ipv4Addr::LOCALHOST, 0))?
        .bind()
        .await?;
    Ok(ep)
}

#[tokio::main]
async fn main() -> anyhow::Result<()> {
    let payload: Vec<u8> = (0..300_000u32).map(|i| (i % 251) as u8).collect();
    let want_blake3 = blake3::hash(&payload);
    let want_sha256 = sha2::Sha256::digest(&payload);

    // Provider A: store + blobs protocol behind a router.
    let lookup_a = MemoryLookup::new();
    let ep_a = endpoint(lookup_a).await?;
    let store_a = MemStore::new();
    let tag = store_a.blobs().add_bytes(payload.clone()).await?;
    println!("added: hash={} format={:?}", tag.hash, tag.format);
    assert_eq!(tag.hash.as_bytes(), want_blake3.as_bytes(), "store hash IS blake3 of bytes");

    let blobs_a = BlobsProtocol::new(&store_a, None);
    let router_a = iroh::protocol::Router::builder(ep_a.clone())
        .accept(iroh_blobs::ALPN, blobs_a)
        .spawn();
    let addr_a = ep_a.addr();
    println!("provider addr: {addr_a:?}");

    // Fetcher B: knows A's full addr (direct sockets) via its own MemoryLookup.
    let lookup_b = MemoryLookup::new();
    lookup_b.add_endpoint_info(addr_a.clone());
    let ep_b = endpoint(lookup_b).await?;
    let store_b = MemStore::new();
    let downloader = store_b.downloader(&ep_b);

    let hash = Hash::from(*want_blake3.as_bytes());
    assert!(!store_b.blobs().has(hash).await?, "B starts without the blob");
    downloader.download(hash, Some(addr_a.id)).await?;
    assert!(store_b.blobs().has(hash).await?, "B has the blob after download");

    let got = store_b.blobs().get_bytes(hash).await?;
    assert_eq!(got.as_ref(), payload.as_slice(), "bytes identical");
    assert_eq!(
        sha2::Sha256::digest(&got).as_slice(),
        want_sha256.as_slice(),
        "sha256 identical (C1 double-check works)"
    );

    println!("OK: peer blob fetch byte+hash identical, no relay, loopback only");
    router_a.shutdown().await?;
    ep_b.close().await;
    Ok(())
}

