//! Probe: two iroh endpoints join the same gossip topic (topic = sha256 of a
//! "lineage root" string), one broadcasts, the other receives. No relay,
//! loopback only. Pins the gossip surface M4 P2 will use.

use std::net::{Ipv4Addr, SocketAddrV4};

use iroh::{address_lookup::memory::MemoryLookup, endpoint::presets, Endpoint, RelayMode};
use iroh_gossip::{
    api::Event,
    net::{Gossip, GOSSIP_ALPN},
    proto::TopicId,
};
use n0_future::StreamExt;
use sha2::Digest;

async fn endpoint(lookup: MemoryLookup) -> anyhow::Result<Endpoint> {
    let ep = Endpoint::builder(presets::Empty)
        .address_lookup(lookup)
        .relay_mode(RelayMode::Disabled)
        .bind_addr(SocketAddrV4::new(Ipv4Addr::LOCALHOST, 0))?
        .bind()
        .await?;
    Ok(ep)
}

#[tokio::main]
async fn main() -> anyhow::Result<()> {
    // topic = derive(lineage_root): sha256 → 32 bytes → TopicId.
    let topic_bytes: [u8; 32] = sha2::Sha256::digest(b"croft.sync-topic/v1:lineage-root-demo").into();
    let topic = TopicId::from_bytes(topic_bytes);
    println!("topic: {topic}");

    let lookup_a = MemoryLookup::new();
    let ep_a = endpoint(lookup_a).await?;
    let gossip_a = Gossip::builder().spawn(ep_a.clone());
    let router_a = iroh::protocol::Router::builder(ep_a.clone())
        .accept(GOSSIP_ALPN, gossip_a.clone())
        .spawn();
    let addr_a = ep_a.addr();

    let lookup_b = MemoryLookup::new();
    lookup_b.add_endpoint_info(addr_a.clone());
    let ep_b = endpoint(lookup_b).await?;
    let gossip_b = Gossip::builder().spawn(ep_b.clone());
    let router_b = iroh::protocol::Router::builder(ep_b.clone())
        .accept(GOSSIP_ALPN, gossip_b.clone())
        .spawn();

    // A subscribes with no bootstrap (it is the rendezvous); B bootstraps via A.
    let topic_a = gossip_a.subscribe_and_join(topic, vec![]);
    let topic_b = gossip_b.subscribe_and_join(topic, vec![addr_a.id]);
    let (b_join, a_join) = tokio::join!(topic_b, topic_a);
    let (sender_b, _recv_b) = b_join?.split();
    let (_sender_a, mut recv_a) = a_join?.split();

    sender_b.broadcast(bytes::Bytes::from_static(b"frontier: hello from B")).await?;

    let deadline = tokio::time::Instant::now() + tokio::time::Duration::from_secs(20);
    loop {
        let ev = tokio::time::timeout_at(deadline, recv_a.next()).await?;
        match ev {
            Some(Ok(Event::Received(msg))) => {
                assert_eq!(msg.content.as_ref(), b"frontier: hello from B");
                println!("OK: gossip broadcast received on topic; content intact");
                break;
            }
            Some(Ok(other)) => println!("event: {other:?}"),
            Some(Err(e)) => anyhow::bail!("gossip error: {e}"),
            None => anyhow::bail!("stream ended"),
        }
    }

    router_a.shutdown().await?;
    router_b.shutdown().await?;
    Ok(())
}

