2	//! the base, materialize the folded tree, and publish it as this device's
3	//! new head. Both devices compute the same fold from the same inputs, so
4	//! they land on byte-identical trees — convergence is derived, not decreed.
5	//!
6	//! Local edits are committed (as this device's head) *before* the fold, so
7	//! materializing the folded tree can never destroy unpublished work: every
8	//! byte the fold replaces is already reachable through this device's head
9	//! chain on the server.
10	
11	use std::collections::BTreeMap;
12	use std::fs;
13	use std::path::Path;
14	
15	use crate::device_head::DeviceHead;
16	use crate::error::SyncError;
17	use crate::fold::fold;
18	use crate::frontier::backup_frontier;
19	use crate::manifest::{DagCbor, FsManifest, ManifestCodec};
20	use crate::materialize::write_verified_file;
21	use crate::state::SyncState;
22	use crate::transport::{verify_content, AccountKey, BlobTransport, ManifestSlot};
23	
