25	#[derive(Debug, Clone)]
26	pub struct ConvergeReport {
27	    /// Files in the converged tree.
28	    pub files: u64,
29	    /// Files this device had to write (fetched from cache/server).
30	    pub files_written: u64,
31	    /// Files this device deleted (deletions that propagated).
32	    pub files_deleted: u64,
33	    /// Conflict-copies the fold preserved (paths).
34	    pub conflicts: Vec<String>,
35	    /// The converged tree's fs-manifest cid (the new shared base).
36	    pub fs_manifest_cid: String,
37	    /// The frontier seq this device's converged head committed at.
38	    pub manifest_seq: u64,
39	}
40	
41	/// Fetch and decode-verify the fs-manifest at `cid`.
42	async fn fetch_manifest<S: BlobTransport + Sync>(
43	    server: &S,
44	    cid: &str,
45	) -> Result<FsManifest, SyncError> {
46	    let bytes = server.get(cid).await?;
47	    verify_content(cid, &bytes)?;
48	    DagCbor.decode(&bytes)
49	}
50	
51	/// Converge `dir` with every other device's head. See the module docs for
52	/// the safety argument; the fold itself is `fold::fold`.
53	///
54	/// # Errors
55	///
56	/// Transport/verification failures, an unverifiable head (rejected outright),
57	/// or filesystem failures during materialization.
58	pub async fn converge<S>(
59	    dir: &Path,
60	    state: &mut SyncState,
61	    server: &S,
62	    device_id: &str,
63	) -> Result<ConvergeReport, SyncError>
64	where
65	    S: BlobTransport + ManifestSlot + AccountKey + Sync,
66	{
67	    // 1. Publish local state first — nothing local is ever at risk after this.
68	    backup_frontier(dir, server, state, device_id).await?;
69	
70	    // 2. Read the frontier; decode + verify every head (self-verified fold:
71	    // an unverifiable head is rejected, never folded).
72	    let frontier = server
73	        .frontier()
74	        .await?
75	        .ok_or_else(|| SyncError::Decode("no frontier to converge with".to_owned()))?;
76	    let verifier = server.keypair().verifying_key();
77	    let mut heads: BTreeMap<String, FsManifest> = BTreeMap::new();
78	    for (dev, head_cid) in &frontier.heads {
79	        let head_bytes = server.get(head_cid).await?;
80	        let head = DeviceHead::decode_verified(&head_bytes, &verifier)?;
81	        heads.insert(dev.clone(), fetch_manifest(server, &head.fs_root).await?);
82	    }
83	
84	    // 3. The base: the last converged tree this device recorded.
85	    let base = match state.config_get("base_fs_root")? {
86	        Some(cid) => Some(fetch_manifest(server, &cid).await?),
87	        None => None,
88	    };
89	
90	    // 4. Fold — pure and deterministic; every device gets the same answer.
91	    let outcome = fold(&heads, base.as_ref())?;
92	    let my_tree = heads.get(device_id).cloned().unwrap_or_default();
93	
94	    // 5. Materialize the delta: write what differs (cache first, then
95	    // server, every chunk verified), delete what the fold dropped.
96	    let mut files_written = 0u64;
97	    let mut files_deleted = 0u64;
98	    for (path, entry) in &outcome.tree.entries {
99	        if my_tree.entries.get(path).is_some_and(|mine| mine == entry) {
100	            continue;
101	        }
102	        let mut content = Vec::with_capacity(usize::try_from(entry.size).unwrap_or(0));
103	        for chunk in &entry.chunks {
104	            let cid = chunk.sha256_hex();
105	            if let Some(bytes) = state.cache.get(&cid)? {
106	                content.extend_from_slice(&bytes);
107	            } else {
108	                let bytes = server.get(&cid).await?;
109	                verify_content(&cid, &bytes)?;
110	                let _ = state.cache.insert(&cid, &bytes)?;
111	                content.extend_from_slice(&bytes);
112	            }
113	        }
114	        write_verified_file(&dir.join(path), path, entry, &content)?;
115	        files_written += 1;
116	        tracing::debug!(path = %path, "converge: written");
117	    }
118	    for path in my_tree.entries.keys() {
119	        if !outcome.tree.entries.contains_key(path) {
120	            let full = dir.join(path);
121	            fs::remove_file(&full).map_err(|e| SyncError::Io { path: full.clone(), source: e })?;
122	            files_deleted += 1;
123	            tracing::debug!(path = %path, "converge: deletion propagated");
124	        }
125	    }
126	
127	    // 6. Publish the converged tree as this device's new head, then record
128	    // it as the shared base for the next fold.
129	    let report = backup_frontier(dir, server, state, device_id).await?;
130	    state.config_set("base_fs_root", &report.fs_manifest_cid)?;
131	
132	    let conflicts: Vec<String> =
133	        outcome.conflicts.iter().map(|c| c.loser_path.clone()).collect();
134	    tracing::info!(
135	        files = outcome.tree.entries.len(),
136	        files_written,
137	        files_deleted,
138	        conflicts = conflicts.len(),
139	        seq = report.manifest_seq,
140	        "converged"
141	    );
142	    Ok(ConvergeReport {
143	        files: outcome.tree.entries.len() as u64,
144	        files_written,
145	        files_deleted,
146	        conflicts,
147	        fs_manifest_cid: report.fs_manifest_cid,
148	        manifest_seq: report.manifest_seq,
149	    })
150	}
