33	    let digest = sha2::Sha256::digest(bytes);
34	    let mut out = String::with_capacity(64);
35	    for b in digest {
36	        use std::fmt::Write;
37	        write!(out, "{b:02x}").expect("write to String cannot fail");
38	    }
39	    out
40	}
41	
42	/// What the peer knows about one sha-256 cid: its blake3 alias, who is
43	/// believed to hold it, and whether the local store holds it.
44	#[derive(Debug, Clone)]
