65	    /// Bind a loopback endpoint, spawn the blobs protocol behind a router,
66	    /// and return a ready peer.
67	    ///
68	    /// # Errors
69	    ///
70	    /// Endpoint bind failures surface as [`SyncError::Transport`].
71	    pub async fn spawn() -> Result<Self, SyncError> {
72	        let lookup = MemoryLookup::new();
73	        let endpoint = Endpoint::builder(presets::Minimal)
74	            .address_lookup(lookup.clone())
75	            .relay_mode(RelayMode::Disabled)
76	            .bind_addr(std::net::SocketAddrV4::new(std::net::Ipv4Addr::LOCALHOST, 0))
