    let fs_root_cid = cid_of(&manifest_bytes);
    a.put(&fs_root_cid, &manifest_bytes).await.expect("put manifest");

    let head = DeviceHead::new_signed("dev-a", 1, &fs_root_cid, None, None, &key);
    let head_bytes = head.encode().expect("encode");
