1	//! The per-tree sync state root: one directory holding the scan index, the
2	//! placeholder store, the chunk cache, and config. Always lives *outside*
3	//! the synced tree (scanning your own mutating sqlite poisons the manifest —
4	//! an M1 lesson encoded as structure).
5	//!
6	//! Layout:
7	//! ```text
8	//! <state_dir>/
9	//!   state.sqlite   scan_index + placeholders + config
10	//!   cache/         cache.sqlite + one file per cached chunk (by cid)
11	//! ```
12	
13	use std::fs;
14	use std::path::{Path, PathBuf};
15	
16	use rusqlite::{Connection, OptionalExtension};
17	use sha2::{Digest, Sha256};
18	
19	use crate::cache::ChunkCache;
20	use crate::error::SyncError;
21	use crate::index::Index;
22	use crate::placeholder::PlaceholderStore;
23	
24	/// The default chunk-cache budget when none was ever configured (256 MiB).
25	pub const DEFAULT_CACHE_BUDGET: u64 = 256 * 1024 * 1024;
26	
27	/// A tree's sync state, opened from its state root.
28	pub struct SyncState {
29	    /// The mtime/size scan fast-path (M1's, now wired in by default).
30	    pub index: Index,
31	    /// The evicted files' logical entries.
32	    pub placeholders: PlaceholderStore,
33	    /// The budgeted chunk cache.
34	    pub cache: ChunkCache,
35	    dir: PathBuf,
36	}
37	
38	impl SyncState {
39	    /// Open (or create) the state root at `dir`. The cache budget comes from
40	    /// the persisted config (default [`DEFAULT_CACHE_BUDGET`]).
41	    ///
42	    /// # Errors
43	    ///
44	    /// Filesystem or sqlite failures.
45	    pub fn open<P: AsRef<Path>>(dir: P) -> Result<Self, SyncError> {
46	        let dir = dir.as_ref().to_path_buf();
47	        fs::create_dir_all(&dir).map_err(|e| SyncError::Io { path: dir.clone(), source: e })?;
48	        let db = dir.join("state.sqlite");
49	        let budget = read_config_u64(&db, "cache_budget")?.unwrap_or(DEFAULT_CACHE_BUDGET);
50	        Ok(Self {
51	            index: Index::open(&db)?,
52	            placeholders: PlaceholderStore::open(&db)?,
53	            cache: ChunkCache::open(dir.join("cache"), budget)?,
54	            dir,
55	        })
56	    }
57	
58	    /// Persist a new cache budget and reopen the cache under it.
59	    ///
60	    /// # Errors
61	    ///
62	    /// Sqlite failures.
63	    pub fn set_cache_budget(&mut self, budget: u64) -> Result<(), SyncError> {
64	        write_config_u64(&self.dir.join("state.sqlite"), "cache_budget", budget)?;
65	        self.cache = ChunkCache::open(self.dir.join("cache"), budget)?;
66	        Ok(())
67	    }
68	
69	    /// The state root directory.
70	    #[must_use]
71	    pub fn dir(&self) -> &Path {
72	        &self.dir
73	    }
74	
75	    /// Read a persisted config value (the frontier keeps `device_counter`,
76	    /// `last_head_cid`, and `base_fs_root` here).
77	    ///
78	    /// # Errors
79	    ///
80	    /// Sqlite failures.
81	    pub fn config_get(&self, key: &str) -> Result<Option<String>, SyncError> {
82	        let conn = config_conn(&self.dir.join("state.sqlite"))?;
83	        let value: Option<String> = conn
84	            .query_row("SELECT value FROM config WHERE key = ?1", [key], |r| r.get(0))
85	            .optional()?;
86	        Ok(value)
87	    }
88	
89	    /// Persist a config value.
90	    ///
91	    /// # Errors
92	    ///
93	    /// Sqlite failures.
94	    pub fn config_set(&self, key: &str, value: &str) -> Result<(), SyncError> {
95	        let conn = config_conn(&self.dir.join("state.sqlite"))?;
96	        conn.execute(
97	            "INSERT INTO config (key, value) VALUES (?1, ?2)
98	             ON CONFLICT(key) DO UPDATE SET value = ?2",
99	            rusqlite::params![key, value],
100	        )?;
101	        Ok(())
102	    }
103	
104	    /// The configured spending ceiling in cents, if any (M5 cost twin).
105	    ///
106	    /// # Errors
107	    ///
108	    /// Sqlite failures; a non-numeric stored value.
109	    pub fn ceiling_cents(&self) -> Result<Option<u64>, SyncError> {
110	        read_config_u64(&self.dir.join("state.sqlite"), "ceiling_cents")
111	    }
112	
113	    /// Set or clear the spending ceiling.
114	    ///
115	    /// # Errors
116	    ///
117	    /// Sqlite failures.
118	    pub fn set_ceiling_cents(&mut self, cents: Option<u64>) -> Result<(), SyncError> {
119	        match cents {
120	            Some(c) => write_config_u64(&self.dir.join("state.sqlite"), "ceiling_cents", c),
121	            None => {
122	                let conn = config_conn(&self.dir.join("state.sqlite"))?;
123	                conn.execute("DELETE FROM config WHERE key = 'ceiling_cents'", [])?;
124	                Ok(())
125	            }
126	        }
127	    }
128	
129	    /// Ledger a completed transfer's bytes (M5). The ledger stores bytes and
130	    /// derives cents over the *total*, exactly as a server statement does —
131	    /// per-sync flooring would under-count against the real bill.
132	    ///
133	    /// # Errors
134	    ///
135	    /// Sqlite failures.
136	    pub fn record_spend_bytes(&self, bytes: u64) -> Result<(), SyncError> {
137	        let ts = std::time::SystemTime::now()
138	            .duration_since(std::time::UNIX_EPOCH)
139	            .map_or(0, |d| d.as_secs());
140	        let conn = spend_conn(&self.dir.join("state.sqlite"))?;
141	        conn.execute(
142	            "INSERT INTO spend (ts, bytes) VALUES (?1, ?2)",
143	            rusqlite::params![ts, bytes],
144	        )?;
145	        Ok(())
146	    }
147	
148	    /// Total transferred bytes on the ledger.
149	    ///
150	    /// # Errors
151	    ///
152	    /// Sqlite failures.
153	    pub fn spent_bytes(&self) -> Result<u64, SyncError> {
154	        let conn = spend_conn(&self.dir.join("state.sqlite"))?;
155	        let total: i64 =
156	            conn.query_row("SELECT COALESCE(SUM(bytes), 0) FROM spend", [], |r| r.get(0))?;
157	        Ok(u64::try_from(total).unwrap_or(0))
158	    }
159	
160	    /// The ledger priced by the server's own tariff, over total bytes.
161	    ///
162	    /// # Errors
163	    ///
164	    /// Sqlite failures.
165	    pub fn spent_cents(&self) -> Result<u64, SyncError> {
166	        Ok(ciss::pricing::postage_cents(self.spent_bytes()?))
167	    }
168	
169	    /// Clear the spend ledger (a new period).
170	    ///
171	    /// # Errors
172	    ///
173	    /// Sqlite failures.
174	    pub fn reset_spend(&self) -> Result<(), SyncError> {
175	        let conn = spend_conn(&self.dir.join("state.sqlite"))?;
176	        conn.execute("DELETE FROM spend", [])?;
177	        Ok(())
178	    }
179	
180	    /// A stable 16-hex identifier for (profile, tree path) — the state root's
181	    /// directory name under the per-user data dir.
182	    #[must_use]
183	    pub fn tree_id(profile: &str, tree: &Path) -> String {
184	        let mut hasher = Sha256::new();
185	        hasher.update(profile.as_bytes());
186	        hasher.update([0]);
187	        hasher.update(tree.as_os_str().as_encoded_bytes());
188	        let digest: [u8; 32] = hasher.finalize().into();
189	        crate::chunk::Hash32(digest).to_hex()[..16].to_owned()
190	    }
191	}
192	
193	fn config_conn(db: &Path) -> Result<Connection, SyncError> {
194	    let conn = Connection::open(db)?;
195	    conn.execute_batch(
196	        "CREATE TABLE IF NOT EXISTS config (key TEXT PRIMARY KEY, value TEXT NOT NULL);",
197	    )?;
198	    Ok(conn)
199	}
200	
201	fn spend_conn(db: &Path) -> Result<Connection, SyncError> {
202	    let conn = Connection::open(db)?;
203	    conn.execute_batch(
204	        "CREATE TABLE IF NOT EXISTS spend (
205	            id INTEGER PRIMARY KEY AUTOINCREMENT,
206	            ts INTEGER NOT NULL,
207	            bytes INTEGER NOT NULL
208	        );",
209	    )?;
210	    Ok(conn)
211	}
212	
213	fn read_config_u64(db: &Path, key: &str) -> Result<Option<u64>, SyncError> {
