            state.config_set("k", "v1").expect("set");
            assert_eq!(state.config_get("k").expect("get"), Some("v1".to_owned()));
            state.config_set("k", "v2").expect("overwrite");
            assert_eq!(state.config_get("k").expect("get"), Some("v2".to_owned()));
