/// Show or adjust the tree's spending ceiling and spend ledger.
fn sync_ceiling(
    global: &GlobalArgs,
    dir: &str,
    cents: Option<u64>,
    clear: bool,
    reset_spend: bool,
    state_dir: Option<&str>,
) -> anyhow::Result<()> {
