//! Probe the deployed relay.croft.ing:
//! 1. Two endpoints on RelayMode::Custom(relay.croft.ing:8443); B fetches a
//!    blob from A knowing ONLY A's relay address (no direct IPs) — proves
//!    the relay path end-to-end.
//! 2. An UNREACHABLE relay + direct loopback addrs — the fetch must still
//!    succeed (graceful degradation; the default cannot break LAN use).

use std::net::{Ipv4Addr, SocketAddrV4};

use iroh::{
    address_lookup::memory::MemoryLookup, endpoint::presets, Endpoint, EndpointAddr, RelayMode,
    RelayUrl, TransportAddr,
};
use iroh_blobs::{store::mem::MemStore, BlobsProtocol, Hash};

async fn endpoint(lookup: MemoryLookup, relay: RelayMode) -> anyhow::Result<Endpoint> {
    Ok(Endpoint::builder(presets::Minimal)
        .address_lookup(lookup)
        .relay_mode(relay)
        .bind_addr(SocketAddrV4::new(Ipv4Addr::UNSPECIFIED, 0))?
        .bind()
        .await?)
}

async fn fetch_via(
    provider_relay: RelayMode,
    fetcher_relay: RelayMode,
    addr_of_a: impl Fn(&Endpoint) -> EndpointAddr,
    label: &str,
) -> anyhow::Result<()> {
    let payload: Vec<u8> = (0..200_000u32).map(|i| (i % 253) as u8).collect();
    let want = blake3::hash(&payload);

    let lookup_a = MemoryLookup::new();
    let ep_a = endpoint(lookup_a, provider_relay).await?;
    let store_a = MemStore::new();
    let tag = store_a.blobs().add_bytes(payload.clone()).await?;
    assert_eq!(tag.hash.as_bytes(), want.as_bytes());
    let blobs_a = BlobsProtocol::new(&store_a, None);
    let router_a = iroh::protocol::Router::builder(ep_a.clone())
        .accept(iroh_blobs::ALPN, blobs_a)
        .spawn();

    let a_addr = addr_of_a(&ep_a);
    println!("[{label}] A dialable at: {a_addr:?}");

    let lookup_b = MemoryLookup::new();
    lookup_b.add_endpoint_info(a_addr.clone());
    let ep_b = endpoint(lookup_b, fetcher_relay).await?;
    let store_b = MemStore::new();
    let downloader = store_b.downloader(&ep_b);
    let hash = Hash::from(*want.as_bytes());
    tokio::time::timeout(
        std::time::Duration::from_secs(60),
        downloader.download(hash, Some(a_addr.id)),
    )
    .await
    .map_err(|_| anyhow::anyhow!("[{label}] download timed out"))??;
    let got = store_b.blobs().get_bytes(hash).await?;
    assert_eq!(got.as_ref(), payload.as_slice(), "[{label}] bytes identical");
    println!("[{label}] OK: blob fetched, byte-identical");

    router_a.shutdown().await?;
    ep_b.close().await;
    Ok(())
}

#[tokio::main]
async fn main() -> anyhow::Result<()> {
    let relay: RelayUrl = "https://relay.croft.ing:8443".parse()?;

    // 1. Relay-only: B knows A ONLY by id + relay — no direct addresses.
    let r = relay.clone();
    fetch_via(
        RelayMode::Custom(relay.clone().into()),
        RelayMode::Custom(relay.clone().into()),
        move |ep| EndpointAddr::from_parts(ep.id(), [TransportAddr::Relay(r.clone())]),
        "relay-only",
    )
