1	//! iroh transport for the ciss-sync engine.
2	//!
3	//! [`IrohPeer`] is a [`BlobTransport`] keyed by the canonical sha-256 cid
4	//! (C1 — the server's address of record) whose bytes live in an iroh-blobs
5	//! store addressed by blake3 — the second hash every `ChunkRef` has carried
6	//! since M1, precisely for this transport. Peer fetches ride iroh's
7	//! Bao-verified streaming (blake3 integrity in transit), and the sha-256 is
8	//! **re-verified on receipt**: a poisoned sha256→blake3 mapping can waste a
9	//! fetch but never corrupt a tree.
10	//!
11	//! [`PeerFirst`] composes an `IrohPeer` over an origin transport (CISS):
12	//! reads prefer the peer and fall back per blob; writes and the keep-set
13	//! stay on the origin, so backup/billing semantics are unchanged.
14	
15	#![warn(missing_docs)]
16	
17	mod mesh;
18	
19	pub use mesh::{addr_from_ticket, ticket_for, MeshPeer, ANNOUNCE_KIND};
20	
21	use std::collections::{HashMap, HashSet};
22	use std::sync::{Arc, Mutex};
23	
24	use ciss_sync::{BlobTransport, SyncError};
25	use iroh::address_lookup::memory::MemoryLookup;
26	use iroh::endpoint::presets;
27	use iroh::{Endpoint, EndpointAddr, EndpointId, RelayMode};
28	use iroh_blobs::store::mem::MemStore;
29	use iroh_blobs::{BlobsProtocol, Hash};
30	use sha2::Digest;
31	
32	fn transport_err(context: &str, e: impl std::fmt::Display) -> SyncError {
33	    SyncError::Transport(format!("iroh {context}: {e}"))
34	}
35	
36	fn sha256_hex(bytes: &[u8]) -> String {
37	    let digest = sha2::Sha256::digest(bytes);
38	    let mut out = String::with_capacity(64);
39	    for b in digest {
40	        use std::fmt::Write;
41	        write!(out, "{b:02x}").expect("write to String cannot fail");
42	    }
43	    out
44	}
45	
46	/// What the peer knows about one sha-256 cid: its blake3 alias, who is
47	/// believed to hold it, and whether the local store holds it.
