async fn receive_loop(
    mut receiver: GossipReceiver,
    sender: GossipSender,
    slot: Arc<Mutex<SlotState>>,
    last_announce: Arc<Mutex<Option<Announcement>>>,
    index: MappingIndex,
    lookup: MemoryLookup,
) {
