55	    let mut a = device("dev-a");
56	    let mut b = device("dev-b");
57	
58	    fs::write(a.dir.path().join("alpha.txt"), b"only on device a").expect("write");
59	    let beta: Vec<u8> = (0..400_000).map(|i| (i % 233) as u8).collect();
60	    fs::write(b.dir.path().join("beta.bin"), &beta).expect("write");
61	    fs::write(a.dir.path().join("notes.txt"), b"A's take on the notes").expect("write");
62	    fs::write(b.dir.path().join("notes.txt"), b"B's rather different notes").expect("write");
63	
64	    backup_frontier(a.dir.path(), &mesh_a, &mut a.state, a.id).await.expect("a backup");
65	    backup_frontier(b.dir.path(), &mesh_b, &mut b.state, b.id).await.expect("b backup");
66	
67	    // Gossip is asynchronous: converge once each device can see the other.
68	    mesh_a.await_devices(1, Duration::from_secs(20)).await.expect("a sees b");
69	    mesh_b.await_devices(1, Duration::from_secs(20)).await.expect("b sees a");
70	
71	    let ra = converge(a.dir.path(), &mut a.state, &mesh_a, a.id).await.expect("a converge");
72	    assert_eq!(ra.conflicts.len(), 1, "the same-path divergence is a conflict");
73	    assert!(a.dir.path().join("beta.bin").exists(), "A received B's file over iroh");
74	    assert_eq!(
75	        fs::read(a.dir.path().join("beta.bin")).expect("read"),
76	        beta,
77	        "peer-served bytes are byte-identical"
78	    );
79	
80	    // A's converge republished its folded tree; B folds against it.
81	    mesh_b.await_devices(1, Duration::from_secs(20)).await.expect("b sees a's new head");
82	    let rb = converge(b.dir.path(), &mut b.state, &mesh_b, b.id).await.expect("b converge");
83	    assert!(b.dir.path().join("alpha.txt").exists(), "B received A's file over iroh");
84	    assert_eq!(ra.fs_manifest_cid, rb.fs_manifest_cid, "both devices derived the SAME tree");
85	
86	    // Both contents of the conflict, on both devices.
87	    for d in [&a, &b] {
88	        let main = fs::read(d.dir.path().join("notes.txt")).expect("read");
89	        let conflicts: Vec<_> = fs::read_dir(d.dir.path())
90	            .expect("dir")
91	            .filter_map(Result::ok)
92	            .map(|e| e.file_name().to_string_lossy().into_owned())
93	            .filter(|n| n.contains(".conflict-"))
94	            .collect();
95	        assert_eq!(conflicts.len(), 1, "exactly one conflict-copy on {}", d.id);
96	        let copy = fs::read(d.dir.path().join(&conflicts[0])).expect("read");
97	        let mut both = [main, copy];
98	        both.sort();
99	        assert_eq!(
100	            both,
101	            [b"A's take on the notes".to_vec(), b"B's rather different notes".to_vec()],
102	            "both contents preserved on {}",
103	            d.id
104	        );
105	    }
106	    assert_converged(&a, &b);
