1	//! The serverless frontier: `MeshPeer` implements the engine's full
2	//! transport surface (`BlobTransport` + `ManifestSlot` + `AccountKey`) over
3	//! iroh alone, so `ciss_sync::converge` runs unchanged with no server.
4	//!
5	//! The trust story does not change from M3: `DeviceHead` records stay
6	//! self-verifying and the fold rejects anything that fails the signature —
7	//! a gossip announcement is only a *hint* (frontier entry + sha256→blake3
8	//! mappings). What changes is the ordering authority: I5's monotonic
9	//! seq-CAS serialized shared-slot writes on one server; serverless, each
10	//! device is the sole writer of its own head slot and its signed per-device
11	//! `counter` already gives per-writer ordering, so the frontier is the
12	//! union of announcements with newest-counter-wins per device.
13	
14	use std::collections::{BTreeMap, HashSet};
15	use std::sync::{Arc, Mutex};
16	use std::time::Duration;
17	
18	use ciss_sync::device_head::DeviceHead;
19	use ciss_sync::manifest::{DagCbor, ManifestCodec, FS_MANIFEST_KIND};
20	use ciss_sync::{BlobTransport, FrontierView, ManifestSlot, SyncError};
21	use iroh::address_lookup::memory::MemoryLookup;
22	use iroh::EndpointAddr;
23	use iroh_blobs::store::mem::MemStore;
24	use iroh_blobs::BlobsProtocol;
25	use iroh_gossip::api::{Event, GossipReceiver, GossipSender};
26	use iroh_gossip::net::{Gossip, GOSSIP_ALPN};
27	use iroh_gossip::proto::TopicId;
28	use n0_future::StreamExt;
29	use sha2::Digest;
30	
31	use crate::{register_mapping, transport_err, IrohPeer, MappingIndex};
32	
33	/// The self-tag every announcement carries.
34	pub const ANNOUNCE_KIND: &str = "croft.sync-announce/v1";
35	
36	const TOPIC_DOMAIN: &str = "croft.sync-topic/v1:";
37	
38	/// One device's head, broadcast on the lineage topic. Advisory only: the
39	/// receiver folds nothing until the `DeviceHead` blob itself verifies.
40	#[derive(Debug, Clone, serde::Serialize, serde::Deserialize)]
41	struct Announcement {
42	    kind: String,
43	    device_id: String,
44	    counter: u64,
45	    head_sha256: String,
46	    head_blake3: [u8; 32],
47	    fs_root_sha256: String,
48	    fs_root_blake3: [u8; 32],
49	    addr: EndpointAddr,
50	}
51	
52	/// The local slot: this device's committed state plus what gossip taught us.
53	#[derive(Debug, Default)]
54	struct SlotState {
55	    seq: Option<u64>,
56	    leaves: Vec<(String, u64)>,
57	    own_head: Option<(String, String)>,
58	    /// `device_id → (counter, head_cid)` from announcements.
59	    remote: BTreeMap<String, (u64, String)>,
60	}
61	
62	/// Merge one announcement into the slot: newest counter wins per device.
63	/// Pure — this is the serverless replacement for the I5 ordering rule.
64	fn merge_announcement(slot: &mut SlotState, device_id: &str, counter: u64, head_cid: &str) -> bool {
65	    match slot.remote.get(device_id) {
66	        Some((have, _)) if *have >= counter => false,
67	        _ => {
68	            slot.remote.insert(device_id.to_owned(), (counter, head_cid.to_owned()));
69	            true
70	        }
71	    }
72	}
73	
74	/// Derive the gossip topic from the lineage root — today the shared account
75	/// key, so every device of the account lands on the same topic with no
76	/// coordination (`multi-device.md` §10: `TopicId = derive(lineage_root)`).
77	fn topic_for(keypair: &ciss::crypto::Keypair) -> TopicId {
78	    let mut hasher = sha2::Sha256::new();
79	    hasher.update(TOPIC_DOMAIN.as_bytes());
80	    hasher.update(keypair.verifying_key().to_bytes());
81	    TopicId::from_bytes(hasher.finalize().into())
82	}
83	
84	/// Encode an [`EndpointAddr`] as a pairing ticket (URL-safe base64 JSON) —
85	/// the one string a user carries between devices; the topic itself is
86	/// derived from the account key, so the ticket is only "where to dial".
87	///
88	/// # Errors
89	///
90	/// [`SyncError::Encode`] if the address fails to serialize.
91	pub fn ticket_for(addr: &EndpointAddr) -> Result<String, SyncError> {
92	    use base64::Engine as _;
93	    let json = serde_json::to_vec(addr).map_err(|e| SyncError::Encode(format!("ticket: {e}")))?;
94	    Ok(base64::engine::general_purpose::URL_SAFE_NO_PAD.encode(json))
95	}
96	
97	/// Decode a pairing ticket back into an [`EndpointAddr`].
98	///
99	/// # Errors
100	///
101	/// [`SyncError::Decode`] on anything that is not a valid ticket.
102	pub fn addr_from_ticket(ticket: &str) -> Result<EndpointAddr, SyncError> {
103	    use base64::Engine as _;
104	    let json = base64::engine::general_purpose::URL_SAFE_NO_PAD
