91	/// A [`BlobTransport`] backed by iroh-blobs: serves its local blobs to peers
92	/// and fetches missing blobs from known providers by blake3 (Bao-verified),
93	/// keyed externally by the canonical sha-256 cid.
94	#[derive(Debug)]
95	pub struct IrohPeer {
96	    endpoint: Endpoint,
97	    router: iroh::protocol::Router,
98	    store: iroh_blobs::api::Store,
99	    downloader: iroh_blobs::api::downloader::Downloader,
100	    lookup: MemoryLookup,
101	    index: MappingIndex,
102	    /// Optional durable alias index (write-through; see `register_mapping`).
103	    aliases: Option<ciss_sync::AliasStore>,
104	}
