106	/// The relay this deployment runs (croft-stack: `relay.croft.ing`, mode B).
107	/// The relay is one transport among several — an unreachable relay degrades
108	/// to direct paths (probe-verified, and pinned by a hermetic test), so this
109	/// default never breaks LAN-only use.
110	pub const DEFAULT_RELAY_URL: &str = "https://relay.croft.ing:8443";
111	
112	/// Resolve an optional relay URL string into a [`RelayMode`].
113	fn relay_mode(relay: Option<&str>) -> Result<RelayMode, SyncError> {
114	    match relay {
115	        None => Ok(RelayMode::Disabled),
116	        Some(url) => {
117	            let parsed: iroh::RelayUrl = url
118	                .parse()
119	                .map_err(|e| SyncError::Decode(format!("relay url {url:?}: {e}")))?;
120	            Ok(RelayMode::Custom(parsed.into()))
121	        }
122	    }
123	}
124	
125	impl IrohPeer {
126	    /// Bind an endpoint (`presets::Minimal`) — the probe-verified recipe
127	    /// shared by [`IrohPeer::spawn`] and the mesh. The bind posture follows
128	    /// the relay choice: relay-less peers bind loopback (the hermetic
129	    /// test/LAN-drill posture), relay-configured peers bind all interfaces
130	    /// (a peer that expects to be dialed from elsewhere must be reachable
131	    /// on more than 127.0.0.1).
132	    pub(crate) async fn bind_endpoint(
133	        lookup: &MemoryLookup,
134	        relay: Option<&str>,
135	    ) -> Result<Endpoint, SyncError> {
136	        let bind_ip = if relay.is_some() {
137	            std::net::Ipv4Addr::UNSPECIFIED
138	        } else {
139	            std::net::Ipv4Addr::LOCALHOST
140	        };
141	        Endpoint::builder(presets::Minimal)
142	            .address_lookup(lookup.clone())
143	            .relay_mode(relay_mode(relay)?)
144	            .bind_addr(std::net::SocketAddrV4::new(bind_ip, 0))
145	            .map_err(|e| transport_err("bind_addr", e))?
146	            .bind()
147	            .await
