149	    }
150	
151	    /// Assemble a peer from parts (the mesh builds the router itself so it
152	    /// can accept the gossip ALPN alongside blobs, and chooses the store —
153	    /// in-memory or fs-backed — plus the durable alias index).
154	    pub(crate) fn from_parts(
155	        endpoint: Endpoint,
156	        router: iroh::protocol::Router,
157	        store: iroh_blobs::api::Store,
158	        lookup: MemoryLookup,
159	        aliases: Option<ciss_sync::AliasStore>,
160	    ) -> Self {
161	        let downloader = store.downloader(&endpoint);
162	        Self {
163	            endpoint,
164	            router,
165	            store,
166	            downloader,
167	            lookup,
168	            index: Arc::new(Mutex::new(HashMap::new())),
169	            aliases,
170	        }
171	    }
172	
173	    /// Bind an endpoint (relay per `relay`; `None` = loopback-only), spawn
174	    /// the blobs protocol behind a router, and return a ready peer.
175	    ///
176	    /// # Errors
177	    ///
