    #[test]
    fn resolve_is_object_over_namespace_over_world() {
        let owner = derive_keypair("m", "policy-owner");
        let did = derive_id(&owner.verifying_key());
        let cid = crate::crypto::sha256_hex(b"obj");
        let alice = "did:plc:alice".to_owned();
