1	//! The CISS implementation of `ciss-sync`'s transport seam.
2	//!
3	//! Lives here — next to the [`Client`] it wraps — rather than in `ciss-sync`,
4	//! because the CLI consumes the engine (`ciss-cli → ciss-sync`); the engine
5	//! depending back on the CLI would be a package cycle. Reusing this crate's
6	//! `Client` keeps the metered-call + `verify_cid` path single-sourced (the
7	//! OQ1 decision), and `HttpCiss` is the only glue.
8	
9	use std::collections::HashSet;
10	use std::path::{Path, PathBuf};
11	
12	use std::collections::BTreeMap;
13	
14	use ciss::crypto::Keypair;
15	use ciss::manifest::{build_manifest, build_manifest_with_heads, ManifestLeaf};
16	use ciss_sync::{
17	    verify_server_cid, AccountKey, BlobTransport, FrontierView, ManifestSlot, SyncError, SyncState,
18	};
19	
20	use crate::client::{session_for, Client, Session};
21	
22	/// This install's stable device label for the M3 frontier: read from the
23	/// profile dir's `device_id` file, generated once (8 random hex) on first use.
24	/// Self-asserted (shared-key era) — a real device key replaces it later.
25	///
26	/// # Errors
27	///
28	/// Filesystem failures reading/creating the file.
29	pub fn device_id(config: &crate::config::Config) -> anyhow::Result<String> {
30	    let path = config.profile_dir().join("device_id");
31	    if let Ok(existing) = std::fs::read_to_string(&path) {
32	        let trimmed = existing.trim().to_owned();
33	        anyhow::ensure!(!trimmed.is_empty(), "empty device_id at {}", path.display());
34	        return Ok(trimmed);
35	    }
36	    let mut raw = [0u8; 4];
37	    getrandom::getrandom(&mut raw).map_err(|e| anyhow::anyhow!("entropy: {e}"))?;
38	    let id: String = raw.iter().map(|b| format!("{b:02x}")).collect();
39	    std::fs::create_dir_all(config.profile_dir())?;
40	    std::fs::write(&path, format!("{id}\n"))?;
41	    tracing::info!(device_id = %id, "generated this install's device id");
42	    Ok(id)
43	}
44	
45	/// The default state root for (profile, tree): `$XDG_DATA_HOME` (or
46	/// `$HOME/.local/share`) `/ciss-ctl/sync/<tree-id>/`. The tree path is
47	/// canonicalized first so `./notes` and `/home/u/notes` share state.
48	///
49	/// # Errors
50	///
51	/// If the tree path cannot be canonicalized or no home directory is set.
52	pub fn default_state_dir(profile: &str, tree: &Path) -> anyhow::Result<PathBuf> {
53	    let canonical = tree
54	        .canonicalize()
55	        .map_err(|e| anyhow::anyhow!("cannot resolve {}: {e}", tree.display()))?;
56	    let data_home = match std::env::var("XDG_DATA_HOME") {
57	        Ok(v) if !v.is_empty() => PathBuf::from(v),
58	        _ => {
59	            let home = std::env::var("HOME")
60	                .map_err(|_| anyhow::anyhow!("neither XDG_DATA_HOME nor HOME is set"))?;
61	            PathBuf::from(home).join(".local/share")
62	        }
63	    };
64	    Ok(data_home
65	        .join("ciss-ctl/sync")
66	        .join(SyncState::tree_id(profile, &canonical)))
67	}
68	
69	/// Resolve which relay the p2p endpoints use. Precedence: `--no-relay` >
70	/// `--relay <url>` > the profile's `relay` file (`disabled` opts out) >
71	/// [`ciss_iroh::DEFAULT_RELAY_URL`]. An unreachable relay degrades to
72	/// direct paths, so the default never breaks LAN-only use.
73	#[must_use]
74	pub fn resolve_relay(
75	    no_relay: bool,
76	    flag: Option<&str>,
77	    profile_setting: Option<&str>,
78	) -> Option<String> {
79	    if no_relay {
80	        return None;
81	    }
82	    if let Some(url) = flag {
83	        return Some(url.to_owned());
84	    }
85	    match profile_setting.map(str::trim) {
86	        Some("disabled") => None,
87	        Some(url) if !url.is_empty() => Some(url.to_owned()),
88	        _ => Some(ciss_iroh::DEFAULT_RELAY_URL.to_owned()),
89	    }
90	}
91	
92	/// The profile's persisted relay setting (`<profile_dir>/relay`, one line:
93	/// a URL or `disabled`), if the file exists.
94	#[must_use]
95	pub fn profile_relay_setting(config: &crate::config::Config) -> Option<String> {
96	    std::fs::read_to_string(config.profile_dir().join("relay")).ok()
97	}
98	
99	/// The per-profile aggregate spend ledger:
100	/// `$XDG_DATA_HOME/ciss-ctl/profiles/<profile>/ledger.sqlite` — one ledger
101	/// for the account, spanning every synced tree.
102	///
103	/// # Errors
104	///
105	/// If no home directory is set, or the directory cannot be created.
106	pub fn profile_ledger(profile: &str) -> anyhow::Result<ciss_sync::SpendLedger> {
107	    let data_home = match std::env::var("XDG_DATA_HOME") {
108	        Ok(v) if !v.is_empty() => PathBuf::from(v),
109	        _ => {
110	            let home = std::env::var("HOME")
111	                .map_err(|_| anyhow::anyhow!("neither XDG_DATA_HOME nor HOME is set"))?;
112	            PathBuf::from(home).join(".local/share")
113	        }
114	    };
115	    let dir = data_home.join("ciss-ctl/profiles").join(profile);
116	    std::fs::create_dir_all(&dir)?;
117	    Ok(ciss_sync::SpendLedger::open(dir.join("ledger.sqlite"), "profile")?)
118	}
