1	//! The **read-policy kind** on the self-assertion substrate: a durable,
2	//! customer-authorized statement of *who may read* a namespace or a single
3	//! object. It is the authorization twin of the manifest — the manifest is
4	//! the customer's signed statement of *what is stored* (the billing base);
5	//! a policy is their statement of *who may see it* (the access base).
6	//!
7	//! Since D1 (the dials plan) the envelope — signatures, Model A/C
8	//! authorization, seq anti-rollback, the provider ack — lives in
9	//! [`crate::assertion`]; this module supplies only what is policy-specific:
10	//! the typed body, its canonical fold (what the signature binds), its
11	//! structural validation, and the resolution logic the read gate uses
12	//! (`world`/`grantees`/`owner`, finest-grain-wins, fail-closed).
13	//!
14	//! A namespace policy is the `policy` kind with no subkey; a per-object
15	//! policy is the same kind with the object cid as the subkey — the
16	//! substrate binds both into the signature, so an object policy can never
17	//! be lifted onto a different object (the old `target_tag` guarantee,
18	//! inherited structurally).
19	
20	use std::collections::HashSet;
21	
22	use serde::{Deserialize, Serialize};
23	
24	use crate::identifiers::Did;
25	
26	/// The assertion kind tag for read policies.
27	pub const POLICY_KIND: &str = "policy";
28	
29	/// Upper bound on an explicit reader list. Groups (a dynamic reader set) are
30	/// a deferred design item; an explicit list is bounded so a single record
31	/// cannot be made unboundedly large.
32	const MAX_READERS: usize = 1024;
33	
34	/// The read-visibility class of a target.
35	#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
36	#[serde(rename_all = "snake_case")]
37	pub enum ReadClass {
38	    /// Public — any caller may read (the PDS-compatible default, invariant Z1).
39	    World,
40	    /// Restricted — only the owner and the DIDs in `readers` may read.
41	    Grantees,
42	    /// Owner-only — only the owner may read; `readers` must be empty.
43	    Owner,
44	}
45	
46	impl ReadClass {
47	    /// The stable tag bound into the signing fold (independent of the serde
48	    /// wire representation, so a serde rename can never silently change a
49	    /// signature's meaning).
50	    fn tag(self) -> &'static str {
51	        match self {
52	            ReadClass::World => "world",
53	            ReadClass::Grantees => "grantees",
54	            ReadClass::Owner => "owner",
55	        }
56	    }
57	}
58	
59	/// The policy kind's body: the fields a policy assertion carries.
60	#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
61	#[serde(deny_unknown_fields)]
62	pub struct PolicyBody {
63	    /// The read-visibility class.
64	    pub read_class: ReadClass,
65	    /// Explicit reader DIDs (only for `grantees`; empty otherwise).
66	    pub readers: Vec<String>,
67	}
68	
69	/// The canonical fold of a policy body — what the assertion signature binds
70	/// beyond the substrate's did/kind/subkey/seq. Readers are sorted and
71	/// length-prefixed; validated DIDs cannot contain a comma, so the join is
72	/// unambiguous.
73	#[must_use]
74	pub fn policy_body_fold(body: &PolicyBody) -> String {
75	    let mut readers = body.readers.clone();
76	    readers.sort();
