1	//! Workflow tier — D4: the receipt-mode dial + bilateral receipts. The
2	//! customer asserts `bilateral` (a seq'd dial, so the provider cannot
3	//! silently revert it); every metered transfer then produces a receipt the
4	//! customer **countersigns** — the period total becomes a sum of
5	//! doubly-signed facts neither side can dispute. The `501` seam is gone
6	//! from the metered path; both verification keys (receipts + acks) are
7	//! published in the well-known document, so the whole proof chain
8	//! verifies offline.
9	
10	mod common;
11	
12	use std::collections::BTreeMap;
13	
14	use ciss::assertion::SignedAssertion;
15	use ciss::crypto::{derive_keypair, public_key_from_hex};
16	use ciss::dials::{
17	    receipt_mode_body_fold, ReceiptModeBody, ReceiptModeChoice, RECEIPT_MODE_DIAL_KIND,
18	};
19	use ciss::identity::derive_id;
20	use ciss::receipts::Receipt;
21	use ciss_cli::client::{session_for, Client};
22	use common::World;
23	
24	fn mode_dial(
25	    did: &str,
26	    seq: u64,
27	    mode: ReceiptModeChoice,
28	    kp: &ciss::crypto::Keypair,
29	) -> Vec<u8> {
30	    let body = ReceiptModeBody { mode };
31	    serde_json::to_vec(&SignedAssertion::sign_owner(
32	        RECEIPT_MODE_DIAL_KIND,
33	        did,
34	        None,
35	        seq,
36	        serde_json::to_value(body).expect("json"),
37	        &receipt_mode_body_fold(&body),
38	        kp,
39	    ))
40	    .expect("serialize")
41	}
42	
43	/// The bilateral loop end-to-end: dial on → upload yields a bilateral
44	/// receipt hash → the customer countersigns → the completed receipt
45	/// verifies under BOTH published keys; a forged countersign is refused;
46	/// an unknown hash 404s; dialing back to unilateral restores the default.
47	#[tokio::test]
48	async fn bilateral_receipts_become_doubly_signed_facts() {
49	    let world = World::spawn().await;
50	    let kp = derive_keypair("flow-master", "cosigner");
51	    let did = derive_id(&kp.verifying_key());
52	    let session = session_for(&kp);
53	    let client = Client::new(world.url(""));
54	
55	    // Opt in: bilateral receipts by customer assertion.
56	    client
57	        .put_assertion(
58	            &did,
59	            RECEIPT_MODE_DIAL_KIND,
60	            None,
61	            &mode_dial(&did, 1, ReceiptModeChoice::Bilateral, &kp),
62	        )
63	        .await
64	        .expect("bilateral asserted");
65	
66	    // A metered upload now yields a bilateral (provider-signed, pending
67	    // countersign) receipt — no 501 anywhere.
68	    let put = client.put_s3(&session, "x.bin", &vec![4u8; 1_000]).await.expect("upload serves");
69	    let receipt_hash = put.receipt_hash.clone().expect("bilateral response carries the receipt hash");
70	    assert_eq!(put.receipt_mode, "bilateral");
71	
72	    // The customer countersigns: sig over the receipt's content hash, under
73	    // the key that derives the DID.
74	    let sig = kp.sign_message(&receipt_hash);
75	    let completed = client
76	        .countersign_receipt(&session, &did, &receipt_hash, &sig)
77	        .await
78	        .expect("countersign accepted");
79	    let receipt: Receipt = serde_json::from_value(completed).expect("completed receipt json");
80	    assert_eq!(receipt.sigs().len(), 2, "both parties have signed");
81	
82	    // The doubly-signed fact verifies offline: both keys come from the
83	    // well-known document (receipts key + the customer's own key).
84	    let doc: serde_json::Value = reqwest::get(world.url("/.well-known/did.json"))
85	        .await
86	        .expect("well-known")
87	        .json()
88	        .await
89	        .expect("json");
90	    let receipt_key_hex = doc["verificationMethod"]
91	        .as_array()
92	        .expect("vm list")
93	        .iter()
94	        .find(|m| m["id"].as_str().is_some_and(|i| i.ends_with("#receipts")))
95	        .and_then(|m| m["publicKeyHex"].as_str())
96	        .expect("the receipt key is published");
97	    let mut keyring = BTreeMap::new();
98	    let provider_id = receipt
99	        .sigs()
100	        .keys()
101	        .find(|k| *k != &did)
102	        .expect("the provider party")
103	        .clone();
104	    keyring.insert(provider_id, public_key_from_hex(receipt_key_hex).expect("key"));
105	    keyring.insert(did.clone(), kp.verifying_key());
106	    assert!(
107	        receipt.verify_bilateral(&keyring),
108	        "the completed receipt verifies under both PUBLISHED-or-owned keys"
109	    );
