131	            &did,
132	            RECEIPT_MODE_DIAL_KIND,
133	            None,
134	            &mode_dial(&did, 2, ReceiptModeChoice::Unilateral, &kp),
135	        )
136	        .await
137	        .expect("back to unilateral");
138	    let put = client.put_s3(&session, "y.bin", &vec![5u8; 500]).await.expect("upload");
139	    assert_eq!(put.receipt_mode, "unilateral");
140	
141	    world.shutdown().await;
142	}

